constexpr qint64 kMotorTraceRecoveryMaxCommandDeltaRawPulse = 5000;

qint64 absTraceRawPulseDelta(qint64 delta)
{
    if(delta == std::numeric_limits<qint64>::min()){
        return std::numeric_limits<qint64>::max();
    }
    return delta < 0 ? -delta : delta;
}

bool motorTraceRecoveryCommandDeltaExceedsLimit(
        const HardwareInterface::MotorTraceRecoveryAxisState& axisState,
        qint64* commandDeltaRawPulse = nullptr,
        qint64* absCommandDeltaRawPulse = nullptr)
{
    qint64 delta = 0;
    qint64 absDelta = 0;
    if(axisState.savedCommandValid && axisState.currentCommandValid){
        delta = axisState.savedCommandRawPulse - axisState.currentCommandRawPulse;
        absDelta = absTraceRawPulseDelta(delta);
    }
    if(commandDeltaRawPulse){
        *commandDeltaRawPulse = delta;
    }
    if(absCommandDeltaRawPulse){
        *absCommandDeltaRawPulse = absDelta;
    }
    return absDelta > kMotorTraceRecoveryMaxCommandDeltaRawPulse;
}

const QString kPoseTrajStraight = QStringLiteral("直线轨迹");
const QString kPoseTrajCircular = QStringLiteral("圆形轨迹");
