const QString kPoseTrajEightShape = QStringLiteral("变姿态8字形轨迹");
const QString kPoseTrajStepAccel = QStringLiteral("阶跃变加速轨迹");
const QString kPoseTrajSineAccel = QStringLiteral("正弦变加速轨迹");
const QString kPoseTrajCubic = QStringLiteral("三次多项式轨迹");
const QString kPoseTrajExternalFile = QStringLiteral("外部轨迹文件");

// 判断控制盒速度清零后是否需要按直线类轨迹重新规划恢复段。
bool isControlBoxStraightReplanResumeMode(const QString& mode)
{
    return mode == kPoseTrajStraight ||
            mode == kPoseTrajLineAccel ||
            mode == kPoseTrajSineAccel ||
            mode == kPoseTrajCubic ||
            mode == kPoseTrajStepAccel ||
            mode == kPoseTrajExternalFile;
}

// 判断控制盒速度清零后是否可按参数曲线的 lambda 恢复。
bool isControlBoxParametricResumeMode(const QString& mode)
{
    return mode == kPoseTrajCircular ||
            mode == kPoseTrajEightShape;
}

// 判断当前轨迹模式是否支持控制盒自动恢复。
bool isControlBoxAutoResumeMode(const QString& mode)
{
    return isControlBoxStraightReplanResumeMode(mode) ||
            isControlBoxParametricResumeMode(mode);
}

