bool udpPlatformTrajectoryPointFinite(const QVector<double>& point)
{
    if(point.size() < 7){
        return false;
    }
    for(int index = 0; index < 7; ++index){
        if(!std::isfinite(point[index])){
            return false;
        }
    }
    return true;
}

bool udpPlatformTrajectoryPoseEquals(const QVector<double>& lhs,
                                     const QVector<double>& rhs)
{
    if(lhs.size() < 7 || rhs.size() < 7){
        return false;
    }
    for(int index = 1; index <= 3; ++index){
        if(std::fabs(lhs[index] - rhs[index]) >
                kUdpV9PchipDuplicatePositionToleranceMm){
            return false;
        }
    }
    for(int index = 4; index <= 6; ++index){
        if(std::fabs(lhs[index] - rhs[index]) >
                kUdpV9PchipDuplicateAngleToleranceRad){
            return false;
        }
    }
    return true;
}

bool udpSameSign(double lhs, double rhs)
{
    return (lhs > 0.0 && rhs > 0.0) || (lhs < 0.0 && rhs < 0.0);
}

QVector<double> udpBuildPchipSlopes(const QVector<double>& time,
                                    const QVector<double>& value)
{
    const int count = time.size();
    QVector<double> slope(count, 0.0);
    if(count != value.size() || count < 2){
        return {};
    }

    QVector<double> h(count - 1, 0.0);
    QVector<double> delta(count - 1, 0.0);
    for(int index = 0; index < count - 1; ++index){
        h[index] = time[index + 1] - time[index];
        if(!std::isfinite(h[index]) || h[index] <= 0.0){
            return {};
        }
        delta[index] = (value[index + 1] - value[index]) / h[index];
        if(!std::isfinite(delta[index])){
            return {};
        }
    }

    if(count == 2){
        slope[0] = delta[0];
        slope[1] = delta[0];
        return slope;
    }

    for(int index = 1; index < count - 1; ++index){
        if(delta[index - 1] == 0.0 ||
                delta[index] == 0.0 ||
                !udpSameSign(delta[index - 1], delta[index])){
            slope[index] = 0.0;
            continue;
        }
        const double w1 = 2.0 * h[index] + h[index - 1];
        const double w2 = h[index] + 2.0 * h[index - 1];
        slope[index] =
                (w1 + w2) / (w1 / delta[index - 1] + w2 / delta[index]);
    }

    slope[0] = ((2.0 * h[0] + h[1]) * delta[0] - h[0] * delta[1]) /
            (h[0] + h[1]);
    if(!udpSameSign(slope[0], delta[0])){
        slope[0] = 0.0;
    }
    else if(!udpSameSign(delta[0], delta[1]) &&
            std::fabs(slope[0]) > std::fabs(3.0 * delta[0])){
        slope[0] = 3.0 * delta[0];
    }

    const int last = count - 1;
    slope[last] = ((2.0 * h[last - 1] + h[last - 2]) * delta[last - 1] -
                   h[last - 1] * delta[last - 2]) /
            (h[last - 1] + h[last - 2]);
    if(!udpSameSign(slope[last], delta[last - 1])){
        slope[last] = 0.0;
    }
    else if(!udpSameSign(delta[last - 1], delta[last - 2]) &&
            std::fabs(slope[last]) > std::fabs(3.0 * delta[last - 1])){
        slope[last] = 3.0 * delta[last - 1];
    }

    return slope;
}

double udpPchipValueAt(const QVector<double>& time,
                       const QVector<double>& value,
                       const QVector<double>& slope,
                       double queryTime)
{
    const int count = time.size();
    if(count == 1){
        return value.front();
    }
    if(queryTime <= time.front()){
        return value.front();
    }
    if(queryTime >= time.back()){
        return value.back();
    }

    int segment = 0;
    while(segment < count - 2 && queryTime > time[segment + 1]){
        ++segment;
    }

    const double h = time[segment + 1] - time[segment];
    const double s = (queryTime - time[segment]) / h;
    const double s2 = s * s;
    const double s3 = s2 * s;
    const double h00 = 2.0 * s3 - 3.0 * s2 + 1.0;
    const double h10 = s3 - 2.0 * s2 + s;
    const double h01 = -2.0 * s3 + 3.0 * s2;
    const double h11 = s3 - s2;
    return h00 * value[segment] +
            h10 * h * slope[segment] +
            h01 * value[segment + 1] +
            h11 * h * slope[segment + 1];
}

bool rebuildUdpPlatformTrajectoryWithPchip(
        const QVector<QVector<double>>& rawPoints,
        double samplePeriodSec,
        QVector<QVector<double>>& rebuiltPoints,
        int* keyPointCount,
        int* mergedDuplicatePointCount,
        QString* errorMessage)
{
    rebuiltPoints.clear();
    if(keyPointCount){
        *keyPointCount = 0;
    }
    if(mergedDuplicatePointCount){
        *mergedDuplicatePointCount = 0;
    }
    if(errorMessage){
        errorMessage->clear();
    }
    if(rawPoints.isEmpty()){
        if(errorMessage){
            *errorMessage = QStringLiteral("没有可重建的轨迹点");
        }
        return false;
    }
    if(!std::isfinite(samplePeriodSec) || samplePeriodSec <= 0.0){
        if(errorMessage){
            *errorMessage = QStringLiteral("采样周期无效");
        }
        return false;
    }

    QVector<QVector<double>> keyPoints;
    keyPoints.reserve(rawPoints.size());
    for(int index = 0; index < rawPoints.size(); ++index){
        const QVector<double>& point = rawPoints[index];
        if(!udpPlatformTrajectoryPointFinite(point)){
            if(errorMessage){
                *errorMessage = QStringLiteral("第 %1 个轨迹点包含非法数据").arg(index + 1);
            }
            return false;
        }
        if(index > 0 && point[0] <= rawPoints[index - 1][0]){
            if(errorMessage){
                *errorMessage = QStringLiteral("第 %1 个轨迹点时间戳不递增").arg(index + 1);
            }
            return false;
        }
        if(index == 0 ||
                !udpPlatformTrajectoryPoseEquals(point, rawPoints[index - 1])){
            keyPoints.push_back(point);
        }
    }

    if(keyPoints.isEmpty()){
        rebuiltPoints = rawPoints;
        return true;
    }
    if(keyPoints.back()[0] < rawPoints.back()[0]){
        keyPoints.push_back(rawPoints.back());
    }

    const int mergedCount = rawPoints.size() - keyPoints.size();
    if(keyPointCount){
        *keyPointCount = keyPoints.size();
    }
    if(mergedDuplicatePointCount){
        *mergedDuplicatePointCount = mergedCount;
    }
    if(mergedCount <= 0 || keyPoints.size() < 2){
        rebuiltPoints = rawPoints;
        return true;
    }

    QVector<double> keyTimes;
    keyTimes.reserve(keyPoints.size());
    for(const QVector<double>& point : keyPoints){
        keyTimes.push_back(point[0]);
    }

    QVector<QVector<double>> dimensionValues(6);
    QVector<QVector<double>> dimensionSlopes(6);
    for(int dimension = 0; dimension < 6; ++dimension){
        dimensionValues[dimension].reserve(keyPoints.size());
        for(const QVector<double>& point : keyPoints){
            dimensionValues[dimension].push_back(point[dimension + 1]);
        }
        dimensionSlopes[dimension] =
                udpBuildPchipSlopes(keyTimes, dimensionValues[dimension]);
        if(dimensionSlopes[dimension].size() != keyTimes.size()){
            if(errorMessage){
                *errorMessage = QStringLiteral("第 %1 个自由度 PCHIP 斜率计算失败")
                        .arg(dimension + 1);
            }
            return false;
        }
    }

    const double startTimeSec = rawPoints.front()[0];
    const double endTimeSec = rawPoints.back()[0];
    rebuiltPoints.reserve(rawPoints.size());
    for(int index = 0; index < rawPoints.size(); ++index){
        QVector<double> point(7, 0.0);
        double queryTime = startTimeSec + static_cast<double>(index) * samplePeriodSec;
        if(index == rawPoints.size() - 1){
            queryTime = endTimeSec;
        }
        point[0] = queryTime;
        for(int dimension = 0; dimension < 6; ++dimension){
            point[dimension + 1] =
                    udpPchipValueAt(keyTimes,
                                    dimensionValues[dimension],
                                    dimensionSlopes[dimension],
                                    queryTime);
        }
        rebuiltPoints.push_back(point);
    }
    return true;
}

