enum class CableForceLimitSignalState {
    Unknown,
    Normal,
    Warning,
    Limit
};

// 将绳力限位指示灯状态转换为日志/样式 key。
const char* cableForceLimitSignalStateKey(CableForceLimitSignalState state)
{
    switch(state){
    case CableForceLimitSignalState::Normal:
        return "normal";
    case CableForceLimitSignalState::Warning:
        return "warning";
    case CableForceLimitSignalState::Limit:
        return "limit";
    case CableForceLimitSignalState::Unknown:
    default:
        return "unknown";
    }
}

// 返回绳力限位指示灯的 Qt 样式表片段。
const char* cableForceLimitSignalStyle(CableForceLimitSignalState state)
{
    switch(state){
    case CableForceLimitSignalState::Normal:
        return "background-color: rgb(35, 180, 90);\n"
               "border: 1px solid rgb(20, 120, 60);\n"
               "border-radius: 6px;";
    case CableForceLimitSignalState::Warning:
        return "background-color: rgb(232, 170, 35);\n"
               "border: 1px solid rgb(170, 115, 20);\n"
               "border-radius: 6px;";
    case CableForceLimitSignalState::Limit:
        return "background-color: rgb(210, 55, 45);\n"
               "border: 1px solid rgb(145, 35, 30);\n"
               "border-radius: 6px;";
    case CableForceLimitSignalState::Unknown:
    default:
        return "background-color: rgb(140, 140, 140);\n"
               "border: 1px solid rgb(95, 95, 95);\n"
               "border-radius: 6px;";
    }
}
