bool isExpectedForceMissingValue(double expectedForce)
{
    return !std::isfinite(expectedForce) ||
            std::fabs(expectedForce) <= kExpectedForceMissingEpsilonN;
}

std::vector<double> positionModeUiPoseToPlatformPose(std::vector<double> pose,
                                                     double rxOffsetRad)
{
    if(pose.size() >= 4){
        pose[3] += rxOffsetRad;
    }
    return pose;
}

std::vector<double> platformPoseToPositionModeUiPose(std::vector<double> pose,
                                                     double rxOffsetRad)
{
    if(pose.size() >= 4){
        pose[3] -= rxOffsetRad;
    }
    return pose;
}

Eigen::Matrix3d platformPoseEulerZYXToRotation(const std::vector<double>& pose)
{
    if(pose.size() < 6){
        return Eigen::Matrix3d::Identity();
    }
    const double roll = pose[3];
    const double pitch = pose[4];
    const double yaw = pose[5];
    const double cRoll = std::cos(roll);
    const double sRoll = std::sin(roll);
    const double cPitch = std::cos(pitch);
    const double sPitch = std::sin(pitch);
    const double cYaw = std::cos(yaw);
    const double sYaw = std::sin(yaw);
    Eigen::Matrix3d rotation;
    rotation << cYaw * cPitch, cYaw * sPitch * sRoll - sYaw * cRoll,
            cYaw * sPitch * cRoll + sYaw * sRoll,
            sYaw * cPitch, sYaw * sPitch * sRoll + cYaw * cRoll,
            sYaw * sPitch * cRoll - cYaw * sRoll,
            -sPitch, cPitch * sRoll, cPitch * cRoll;
    return rotation;
}

double platformPoseOrientationDistanceRad(const std::vector<double>& lhs,
                                          const std::vector<double>& rhs)
{
    if(lhs.size() < 6 || rhs.size() < 6){
        return std::numeric_limits<double>::infinity();
    }
    const Eigen::Matrix3d relative =
            platformPoseEulerZYXToRotation(lhs).transpose() *
            platformPoseEulerZYXToRotation(rhs);
    const double cosine = std::max(-1.0, std::min(1.0,
                         (relative.trace() - 1.0) * 0.5));
    return std::acos(cosine);
}

int forceSensorTraceSamplePeriodUsFromHz(int sampleHz)
{
    const int boundedHz = std::min(std::max(sampleHz, 10), 2000);
    return boundedHz >= 1000 ?
                kForceSensorTraceMinPeriodUs :
                kForceSensorTraceMaxPeriodUs;
}

std::vector<double> smoothVisualizationVector(const std::vector<double>& raw,
                                              std::vector<double>& smoothed,
                                              bool enabled,
                                              double dtSec,
                                              double tauSec)
{
    if(raw.size() < 6){
        smoothed.clear();
        return raw;
    }
    std::vector<double> output(raw.begin(), raw.begin() + 6);
    if(!enabled || !std::isfinite(tauSec) || tauSec <= 0.0){
        smoothed.clear();
        return output;
    }

    if(!std::isfinite(dtSec) || dtSec <= 0.0){
        if(smoothed.size() >= 6){
            return std::vector<double>(smoothed.begin(), smoothed.begin() + 6);
        }
        smoothed = output;
        return output;
    }

    if(smoothed.size() < 6){
        smoothed = output;
        return smoothed;
    }

    const double alpha = std::min(1.0, std::max(0.0, dtSec / (tauSec + dtSec)));
    for(int i=0; i<6; ++i){
        if(!std::isfinite(output[i])){
            output[i] = smoothed[i];
            continue;
        }
        if(!std::isfinite(smoothed[i])){
            smoothed[i] = output[i];
            continue;
        }
        smoothed[i] += alpha * (output[i] - smoothed[i]);
        output[i] = smoothed[i];
    }
    return output;
}

template <typename T>
T* findOptionalUiObject(const QWidget* root, const char* objectName)
{
    return root ? root->findChild<T*>(QString::fromLatin1(objectName)) : nullptr;
}

template <typename T>
T* findOptionalUiObject(const QWidget* root, const QString& objectName)
{
    return root ? root->findChild<T*>(objectName) : nullptr;
}

bool optionalCheckBoxChecked(const QWidget* root, const char* objectName, bool fallback = false)
{
    if(QCheckBox* checkBox = findOptionalUiObject<QCheckBox>(root, objectName)){
        return checkBox->isChecked();
    }
    return fallback;
}

void optionalCheckBoxSetChecked(QWidget* root, const char* objectName, bool checked)
{
    if(QCheckBox* checkBox = findOptionalUiObject<QCheckBox>(root, objectName)){
        checkBox->setChecked(checked);
    }
}

void optionalCheckBoxSetChecked(QWidget* root, const QString& objectName, bool checked)
{
    if(QCheckBox* checkBox = findOptionalUiObject<QCheckBox>(root, objectName)){
        checkBox->setChecked(checked);
    }
}

void ensureCheckBoxInSplitter(QWidget* root,
                              const char* splitterName,
                              const char* objectName,
                              const QString& text,
                              const QString& toolTip,
                              int insertIndex)
{
    if(!root || findOptionalUiObject<QCheckBox>(root, objectName)){
        return;
    }
    QSplitter* splitter = findOptionalUiObject<QSplitter>(root, splitterName);
    if(!splitter){
        return;
    }
    QCheckBox* checkBox = new QCheckBox(text, splitter);
    checkBox->setObjectName(QString::fromLatin1(objectName));
    checkBox->setToolTip(toolTip);
    checkBox->setSizePolicy(QSizePolicy::Fixed, QSizePolicy::Fixed);
    const int boundedIndex = std::min(std::max(insertIndex, 0), splitter->count());
    splitter->insertWidget(boundedIndex, checkBox);
}

QCheckBox* ensureCheckBoxInLayout(QWidget* root,
                                  const char* layoutName,
                                  const char* objectName,
                                  const QString& text,
                                  const QString& toolTip,
                                  int insertIndex = -1)
{
    if(!root){
        return nullptr;
    }
    if(QCheckBox* existing = findOptionalUiObject<QCheckBox>(root, objectName)){
        return existing;
    }

    QLayout* layout = findOptionalUiObject<QLayout>(root, layoutName);
    if(!layout){
        return nullptr;
    }

    QWidget* parentWidget = layout->parentWidget() ? layout->parentWidget() : root;
    QCheckBox* checkBox = new QCheckBox(text, parentWidget);
    checkBox->setObjectName(QString::fromLatin1(objectName));
    checkBox->setToolTip(toolTip);
    checkBox->setSizePolicy(QSizePolicy::Fixed, QSizePolicy::Fixed);

    if(QBoxLayout* boxLayout = qobject_cast<QBoxLayout*>(layout)){
        const int boundedIndex = insertIndex < 0 ?
                    boxLayout->count() :
                    std::min(std::max(insertIndex, 0), boxLayout->count());
        boxLayout->insertWidget(boundedIndex, checkBox);
    }
    else{
        layout->addWidget(checkBox);
    }
    return checkBox;
}

QPushButton* ensureButtonInLayout(QWidget* root,
                                  const char* layoutName,
                                  const char* objectName,
                                  const QString& text,
                                  const QString& toolTip,
                                  int insertIndex = -1)
{
    if(!root){
        return nullptr;
    }
    if(QPushButton* existing = findOptionalUiObject<QPushButton>(root, objectName)){
        return existing;
    }

    QLayout* layout = findOptionalUiObject<QLayout>(root, layoutName);
    if(!layout){
        return nullptr;
    }

    QWidget* parentWidget = layout->parentWidget() ? layout->parentWidget() : root;
    QPushButton* button = new QPushButton(text, parentWidget);
    button->setObjectName(QString::fromLatin1(objectName));
    button->setToolTip(toolTip);
    button->setSizePolicy(QSizePolicy::Fixed, QSizePolicy::Fixed);

    if(QBoxLayout* boxLayout = qobject_cast<QBoxLayout*>(layout)){
        const int boundedIndex = insertIndex < 0 ?
                    boxLayout->count() :
                    std::min(std::max(insertIndex, 0), boxLayout->count());
        boxLayout->insertWidget(boundedIndex, button);
    }
    else{
        layout->addWidget(button);
    }
    return button;
}

