ControlWorker::ForceFeedForwardOnlyDirectionalProfile
forceFeedForwardOnlyDirectionalProfileFromUi(const QWidget* root, const char* prefix)
{
    ControlWorker::ForceFeedForwardOnlyDirectionalProfile profile;
    profile.enabled = true;
    if(QComboBox* comboBox =
            findOptionalUiObject<QComboBox>(
                root,
                ffOnlyDirectionalObjectName(prefix, "DynamicTrackMode"))){
        profile.dynamicTrackMode =
                static_cast<ControlWorker::ForcePid0525DynamicTrackMode>(
                    currentComboDataInt(
                        comboBox,
                        kDefaultForceFeedForwardOnlyDirectionalTrackMode));
    }
    profile.useBangBangPretension =
            optionalCheckBoxChecked(
                root,
                qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                       "UseBangBangPretension")),
                kDefaultForceFeedForwardOnlyDirectionalUseBangBangPretension);
    profile.frictionCoulombNm =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "FrictionCoulombNm")),
                                 kDefaultForceFeedForwardOnlyFrictionCoulombNm);
    profile.frictionViscousNmPerRadPerSec =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "FrictionViscousNmPerRadPerSec")),
                                 kDefaultForceFeedForwardOnlyFrictionViscousNmPerRadPerSec);
    profile.frictionVelocityDeadbandRadPerSec =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "FrictionVelocityDeadbandRadPerSec")),
                                 kDefaultForceFeedForwardOnlyFrictionVelocityDeadbandRadPerSec);
    profile.staticFrictionEnabled =
            optionalCheckBoxChecked(root,
                                    qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                           "StaticFrictionEnabled")),
                                    kDefaultForceFeedForwardOnlyStaticFrictionEnabled);
    profile.staticFrictionScale =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "StaticFrictionScale")),
                                 0.5);
    profile.staticFrictionForceRateDeadbandNPerSec =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "StaticFrictionForceRateDeadbandNPerSec")),
                                 kDefaultForceFeedForwardOnlyStaticFrictionForceRateDeadbandNPerSec);
    profile.staticFrictionVelocityFadeStartRadPerSec =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "StaticFrictionVelocityFadeStartRadPerSec")),
                                 kDefaultForceFeedForwardOnlyStaticFrictionVelocityFadeStartRadPerSec);
    profile.staticFrictionVelocityFadeEndRadPerSec =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "StaticFrictionVelocityFadeEndRadPerSec")),
                                 kDefaultForceFeedForwardOnlyStaticFrictionVelocityFadeEndRadPerSec);
    profile.staticFrictionMechanicalDirectionEnabled =
            optionalCheckBoxChecked(root,
                                    qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                           "StaticFrictionMechanicalDirectionEnabled")),
                                    kDefaultForceFeedForwardOnlyStaticFrictionMechanicalDirectionEnabled);
    profile.staticFrictionExitBlendEnabled =
            optionalCheckBoxChecked(root,
                                    qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                           "StaticFrictionExitBlendEnabled")),
                                    kDefaultForceFeedForwardOnlyStaticFrictionExitBlendEnabled);
    profile.staticFrictionExitBlendTimeConstantSec =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "StaticFrictionExitBlendTimeConstantSec")),
                                 kDefaultForceFeedForwardOnlyStaticFrictionExitBlendTimeConstantSec);
    profile.inertiaScale =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "InertiaScale")),
                                 kDefaultForceFeedForwardOnlyInertiaScale);
    profile.trackTorqueSlewRateNmPerSec =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "TrackTorqueSlewNmPerSec")),
                                 kDefaultForceFeedForwardOnlyDirectionalTrackSlewNmPerSec);
    profile.trackBlendTimeSec =
            optionalSpinBoxValue(root,
                                 qPrintable(ffOnlyDirectionalObjectName(prefix,
                                                                         "TrackBlendTimeSec")),
                                 kDefaultForceFeedForwardOnlyDirectionalTrackBlendTimeSec);
    return profile;
}

