QString optionalComboCurrentText(const QWidget* root, const char* objectName, const QString& fallback = QString())
{
    if(QComboBox* comboBox = findOptionalUiObject<QComboBox>(root, objectName)){
        return comboBox->currentText();
    }
    return fallback;
}

int optionalComboCurrentDataInt(const QWidget* root, const char* objectName, int fallback = 0)
{
    if(QComboBox* comboBox = findOptionalUiObject<QComboBox>(root, objectName)){
        const QVariant data = comboBox->currentData();
        if(data.isValid()){
            return data.toInt();
        }
        return comboBox->currentIndex();
    }
    return fallback;
}

void optionalComboSetCurrentData(QWidget* root, const char* objectName, int value)
{
    if(QComboBox* comboBox = findOptionalUiObject<QComboBox>(root, objectName)){
        const int index = comboBox->findData(value);
        comboBox->setCurrentIndex(index >= 0 ? index : 0);
    }
}

using ComboOption = std::pair<QString, int>;

bool comboOptionsMatch(const QComboBox* comboBox,
                       const std::vector<ComboOption>& options)
{
    if(!comboBox || comboBox->count() != static_cast<int>(options.size())){
        return false;
    }

    for(int i=0; i<static_cast<int>(options.size()); ++i){
        if(comboBox->itemText(i) != options[i].first ||
                comboBox->itemData(i, Qt::UserRole).toInt() != options[i].second){
            return false;
        }
    }
    return true;
}

void replaceComboOptions(QComboBox* comboBox,
                         const std::vector<ComboOption>& options)
{
    if(!comboBox){
        return;
    }

    comboBox->clear();
    for(const ComboOption& option : options){
        comboBox->addItem(option.first, option.second);
    }
}

