QString safetyWarningDisplayName(int faultCode)
{
    if(static_cast<SafetyMonitor::FaultCode>(faultCode) ==
            SafetyMonitor::FaultCode::WorkspaceExceeded){
        return QStringLiteral("工作空间边缘");
    }
    return safetyFaultDisplayName(faultCode);
}

QString safetyEventDisplayName(const QString& eventType)
{
    if(eventType == QStringLiteral("fault_triggered")){
        return QStringLiteral("故障触发");
    }
    if(eventType == QStringLiteral("fault_warning")){
        return QStringLiteral("故障预警");
    }
    if(eventType == QStringLiteral("fault_warning_cleared")){
        return QStringLiteral("故障预警解除");
    }
    if(eventType == QStringLiteral("fault_followup")){
        return QStringLiteral("后续故障记录");
    }
    if(eventType == QStringLiteral("fault_repeated")){
        return QStringLiteral("重复安全故障记录");
    }
    if(eventType == QStringLiteral("fault_latch_cleared")){
        return QStringLiteral("故障锁存清除");
    }
    if(eventType == QStringLiteral("fault_reset_rejected")){
        return QStringLiteral("故障复位拒绝");
    }
    if(eventType == QStringLiteral("manual_emergency_request")){
        return QStringLiteral("界面软件急停请求");
    }
    if(eventType == QStringLiteral("control_box_software_emergency_stop_request")){
        return QStringLiteral("手柄控制盒抱闸请求");
    }
    if(eventType == QStringLiteral("software_exception_guard_startup_notice")){
        return QStringLiteral("软件异常捕获启动提示");
    }
    if(eventType == QStringLiteral("startup_self_check_passed")){
        return QStringLiteral("启动系统自检通过");
    }
    if(eventType == QStringLiteral("startup_self_check_failed")){
        return QStringLiteral("启动系统自检未通过");
    }
    return eventType.isEmpty() ? QStringLiteral("未分类事件") : eventType;
}

QString connectionStateDisplayText(HardwareInterface::ConnectionState state)
{
    switch(state){
    case HardwareInterface::ConnectionState::Connected:
        return QStringLiteral("连接");
    case HardwareInterface::ConnectionState::Disabled:
        return QStringLiteral("未使能");
    case HardwareInterface::ConnectionState::Fault:
        return QStringLiteral("异常");
    case HardwareInterface::ConnectionState::Disconnected:
    default:
        return QStringLiteral("断开");
    }
}

QString connectionStateStyle(HardwareInterface::ConnectionState state)
{
    switch(state){
    case HardwareInterface::ConnectionState::Connected:
        return QStringLiteral(
                    "QLabel { color: #166534; background: #dcfce7; border: 1px solid #86efac; "
                    "border-radius: 6px; padding: 4px 6px; font-weight: 700; }");
    case HardwareInterface::ConnectionState::Disabled:
        return QStringLiteral(
                    "QLabel { color: #9a3412; background: #ffedd5; border: 1px solid #fdba74; "
                    "border-radius: 6px; padding: 4px 6px; font-weight: 700; }");
    case HardwareInterface::ConnectionState::Fault:
        return QStringLiteral(
                    "QLabel { color: #991b1b; background: #fee2e2; border: 1px solid #fca5a5; "
                    "border-radius: 6px; padding: 4px 6px; font-weight: 700; }");
    case HardwareInterface::ConnectionState::Disconnected:
    default:
        return QStringLiteral(
                    "QLabel { color: #475569; background: #e2e8f0; border: 1px solid #cbd5e1; "
                    "border-radius: 6px; padding: 4px 6px; font-weight: 600; }");
    }
}

bool shouldPersistParameterWidget(const QWidget* widget)
{
    if(!widget){
        return false;
    }
    if(widget->objectName().isEmpty() || widget->objectName().startsWith(QStringLiteral("qt_"))){
        return false;
    }
    if(widget->property("skipConfig").toString() == QStringLiteral("true")){
        return false;
    }
    return qobject_cast<const QSpinBox*>(widget) ||
            qobject_cast<const QDoubleSpinBox*>(widget) ||
            qobject_cast<const QCheckBox*>(widget) ||
            qobject_cast<const QRadioButton*>(widget) ||
            qobject_cast<const QComboBox*>(widget);
}

