bool looksLikeForcePidParameterMap(const QJsonObject& values)
{
    const QStringList forceNames = forcePidAutoSaveWidgetNames();
    int forceFieldCount = 0;
    for(auto it = values.constBegin(); it != values.constEnd(); ++it){
        if(forceNames.contains(it.key())){
            ++forceFieldCount;
            continue;
        }
        if(it.key() == QStringLiteral("profile_type") ||
                it.key() == QStringLiteral("schema_version") ||
                it.key() == QStringLiteral("saved_at")){
            continue;
        }
        return false;
    }
    return forceFieldCount > 0;
}

