QJsonObject liteForcePidDefaultWidgetValues()
{
    QJsonObject values = builtInForcePidDefaultWidgetValues();
    values.insert(QStringLiteral("devFCFeedForwardOnlyTestMode"), true);
    values.insert(QStringLiteral("motorTorqueLimitNm"), kLiteTorqueLimitNm);

    const QStringList expectedForceNames = {
        QStringLiteral("mainForceSensorExp"),
        QStringLiteral("mainForceSensorExp_2"),
        QStringLiteral("mainForceSensorExp_3"),
        QStringLiteral("mainForceSensorExp_4"),
        QStringLiteral("mainForceSensorExp_5"),
        QStringLiteral("mainForceSensorExp_6"),
        QStringLiteral("mainForceSensorExp_7"),
        QStringLiteral("mainForceSensorExp_8")
    };
    for(const QString& name : expectedForceNames){
        values.insert(name, 0.0);
    }

    return values;
}

QString forcePidJsonValueText(const QJsonValue& value)
{
    if(value.isString()){
        return value.toString();
    }
    if(value.isBool()){
        return value.toBool() ? QStringLiteral("true") : QStringLiteral("false");
    }
    if(value.isDouble()){
        return QLocale::c().toString(value.toDouble(), 'g', 15);
    }
    if(value.isNull()){
        return QStringLiteral("null");
    }
    return QStringLiteral("类型不受支持");
}

QString buildParameterValidationMessage(const QString& profileName,
                                        const QStringList& missingItems,
                                        const QStringList& invalidItems,
                                        const QStringList& unavailableItems)
{
    QStringList sections;
    if(!missingItems.isEmpty()){
        sections << QStringLiteral("%1文件不完整，缺失 %2 项参数：%3")
                    .arg(profileName)
                    .arg(missingItems.size())
                    .arg(missingItems.join(QStringLiteral("，")));
    }
    if(!invalidItems.isEmpty()){
        sections << QStringLiteral("%1文件包含 %2 项错误参数：%3")
                    .arg(profileName)
                    .arg(invalidItems.size())
                    .arg(invalidItems.join(QStringLiteral("，")));
    }
    if(!unavailableItems.isEmpty()){
        sections << QStringLiteral("程序内部有 %1 项默认配置无法应用：%2")
                    .arg(unavailableItems.size())
                    .arg(unavailableItems.join(QStringLiteral("，")));
    }
    if(sections.isEmpty()){
        return QString();
    }

    sections << QStringLiteral("缺失或错误参数已经按照默认值配置");
    return QStringLiteral("参数校验不通过：%1")
            .arg(sections.join(QStringLiteral("；")));
}

bool applyForcePidJsonValueToWidget(QWidget* widget, const QJsonValue& value)
{
    if(!widget){
        return false;
    }

    const QSignalBlocker blocker(widget);
    if(QSpinBox* spinBox = qobject_cast<QSpinBox*>(widget)){
        bool ok = false;
        double number = 0.0;
        if(value.isDouble()){
            number = value.toDouble();
            ok = std::isfinite(number) && std::floor(number) == number;
        }
        else if(value.isString()){
            number = value.toString().toDouble(&ok);
            ok = ok && std::isfinite(number) && std::floor(number) == number;
        }
        if(!ok || number < spinBox->minimum() || number > spinBox->maximum()){
            return false;
        }
        spinBox->setValue(static_cast<int>(number));
        return true;
    }
    if(QDoubleSpinBox* spinBox = qobject_cast<QDoubleSpinBox*>(widget)){
        bool ok = false;
        double number = 0.0;
        if(value.isDouble()){
            number = value.toDouble();
            ok = std::isfinite(number);
        }
        else if(value.isString()){
            number = value.toString().toDouble(&ok);
            ok = ok && std::isfinite(number);
        }
        if(!ok || number < spinBox->minimum() || number > spinBox->maximum()){
            return false;
        }
        spinBox->setValue(number);
        return true;
    }

    const auto boolValue = [&value](bool* ok){
        *ok = true;
        if(value.isBool()){
            return value.toBool();
        }
        if(value.isDouble() && (value.toDouble() == 0.0 || value.toDouble() == 1.0)){
            return value.toDouble() == 1.0;
        }
        if(value.isString()){
            const QString text = value.toString().trimmed().toLower();
            if(text == QStringLiteral("true") || text == QStringLiteral("1")){
                return true;
            }
            if(text == QStringLiteral("false") || text == QStringLiteral("0")){
                return false;
            }
        }
        *ok = false;
        return false;
    };
    if(QCheckBox* checkBox = qobject_cast<QCheckBox*>(widget)){
        bool ok = false;
        const bool checked = boolValue(&ok);
        if(!ok){
            return false;
        }
        checkBox->setChecked(checked);
        return true;
    }
    if(QRadioButton* radioButton = qobject_cast<QRadioButton*>(widget)){
        bool ok = false;
        const bool checked = boolValue(&ok);
        if(!ok){
            return false;
        }
        radioButton->setChecked(checked);
        return true;
    }
    if(QComboBox* comboBox = qobject_cast<QComboBox*>(widget)){
        int index = -1;
        if(value.isDouble()){
            index = comboBox->findData(value.toInt());
        }
        else if(value.isString()){
            QString text = value.toString().trimmed();
            if(comboBox->objectName() == QStringLiteral("devForceControlOutputMode") &&
                    text == QStringLiteral("力矩PID")){
                text = QStringLiteral("0624pid");
            }
            index = comboBox->findText(text, Qt::MatchExactly);
            if(index < 0 && text.contains(QStringLiteral("前馈"), Qt::CaseInsensitive)){
                index = comboBox->findData(static_cast<int>(
                    ControlWorker::ForcePid0525DynamicTrackMode::FeedForwardOnly));
            }
            if(index < 0 && (text.contains(QStringLiteral("A+C"), Qt::CaseInsensitive) ||
                             text.compare(QStringLiteral("AC"), Qt::CaseInsensitive) == 0)){
                index = comboBox->findData(static_cast<int>(
                    ControlWorker::ForcePid0525DynamicTrackMode::AC));
            }
        }
        if(index < 0){
            return false;
        }
        comboBox->setCurrentIndex(index);
        return true;
    }
    return false;
}

QJsonValue forcePidWidgetJsonValue(QWidget* widget)
{
    if(QSpinBox* spinBox = qobject_cast<QSpinBox*>(widget)){
        return spinBox->value();
    }
    if(QDoubleSpinBox* spinBox = qobject_cast<QDoubleSpinBox*>(widget)){
        return spinBox->value();
    }
    if(QCheckBox* checkBox = qobject_cast<QCheckBox*>(widget)){
        return checkBox->isChecked();
    }
    if(QRadioButton* radioButton = qobject_cast<QRadioButton*>(widget)){
        return radioButton->isChecked();
    }
    if(QComboBox* comboBox = qobject_cast<QComboBox*>(widget)){
        return comboBox->currentText();
    }
    return QJsonValue();
}

bool parameterJsonValueToFiniteDouble(const QJsonValue& value, double* number)
{
    bool ok = false;
    double parsed = 0.0;
    if(value.isDouble()){
        parsed = value.toDouble();
        ok = true;
    }
    else if(value.isString()){
        parsed = value.toString().toDouble(&ok);
    }
    if(!ok || !std::isfinite(parsed)){
        return false;
    }
    if(number){
        *number = parsed;
    }
    return true;
}

bool parameterJsonValueToBool(const QJsonValue& value, bool* checked)
{
    if(value.isBool()){
        if(checked){
            *checked = value.toBool();
        }
        return true;
    }
    if(value.isDouble() && (value.toDouble() == 0.0 || value.toDouble() == 1.0)){
        if(checked){
            *checked = value.toDouble() == 1.0;
        }
        return true;
    }
    if(value.isString()){
        const QString text = value.toString().trimmed().toLower();
        if(text == QStringLiteral("true") || text == QStringLiteral("1") ||
                text == QStringLiteral("是") || text == QStringLiteral("开")){
            if(checked){
                *checked = true;
            }
            return true;
        }
        if(text == QStringLiteral("false") || text == QStringLiteral("0") ||
                text == QStringLiteral("否") || text == QStringLiteral("关")){
            if(checked){
                *checked = false;
            }
            return true;
        }
    }
    return false;
}

bool canApplyParameterConfigJsonValueToWidget(QWidget* widget, const QJsonValue& value)
{
    if(!widget){
        return false;
    }
    if(QSpinBox* spinBox = qobject_cast<QSpinBox*>(widget)){
        double number = 0.0;
        if(!parameterJsonValueToFiniteDouble(value, &number) ||
                std::floor(number) != number){
            return false;
        }
        return number >= spinBox->minimum() && number <= spinBox->maximum();
    }
    if(QDoubleSpinBox* spinBox = qobject_cast<QDoubleSpinBox*>(widget)){
        double number = 0.0;
        if(!parameterJsonValueToFiniteDouble(value, &number)){
            return false;
        }
        if(widget->objectName() == QStringLiteral("mainPosModeTargetStepTime") &&
                number > 0.0 && number < 1.0){
            number *= 1000.0;
        }
        return number >= spinBox->minimum() && number <= spinBox->maximum();
    }
    if(qobject_cast<QCheckBox*>(widget) || qobject_cast<QRadioButton*>(widget)){
        return parameterJsonValueToBool(value, nullptr);
    }
    if(QComboBox* comboBox = qobject_cast<QComboBox*>(widget)){
        if(value.isDouble()){
            return comboBox->findData(value.toInt()) >= 0;
        }
        if(!value.isString()){
            return false;
        }
        QString text = value.toString().trimmed();
        if(comboBox->objectName().startsWith(QStringLiteral("axisType"))){
            return text.isEmpty() ||
                    text == QStringLiteral("/") ||
                    text.contains(QStringLiteral("电机"));
        }
        if(comboBox->objectName() == QStringLiteral("devForceControlOutputMode") &&
                text == QStringLiteral("力矩PID")){
            text = QStringLiteral("0624pid");
        }
        return comboBox->isEditable() ||
                comboBox->findText(text, Qt::MatchExactly) >= 0 ||
                (text.contains(QStringLiteral("前馈"), Qt::CaseInsensitive) &&
                 comboBox->findData(static_cast<int>(
                                        ControlWorker::ForcePid0525DynamicTrackMode::FeedForwardOnly)) >= 0) ||
                ((text.contains(QStringLiteral("A+C"), Qt::CaseInsensitive) ||
                  text.compare(QStringLiteral("AC"), Qt::CaseInsensitive) == 0) &&
                 comboBox->findData(static_cast<int>(
                                        ControlWorker::ForcePid0525DynamicTrackMode::AC)) >= 0);
    }
    return false;
}

QJsonObject applyAndCompleteForcePidWidgetValues(QObject* root,
                                                 const QJsonObject& suppliedValues,
                                                 QString* warningMessage)
{
    QJsonObject source = suppliedValues;
    const auto copyFirstAvailableNumber =
            [&source](const char* targetName,
                      std::initializer_list<const char*> sourceNames){
        const QString target = QString::fromLatin1(targetName);
        if(source.contains(target)){
            return;
        }
        for(const char* sourceName : sourceNames){
            const QJsonValue value = source.value(QString::fromLatin1(sourceName));
            if(value.isDouble()){
                source.insert(target, value);
                return;
            }
            if(value.isString()){
                bool ok = false;
                const double number = value.toString().toDouble(&ok);
                if(ok && std::isfinite(number)){
                    source.insert(target, number);
                    return;
                }
            }
        }
    };
    copyFirstAvailableNumber("devFCKp", {
                                 "forcePidTuningKp",
                                 "cfg_pid_kp_s1", "cfg_pid_kp_s2",
                                 "cfg_pid_kp_s3", "cfg_pid_kp_s4",
                                 "cfg_pid_kp_s5", "cfg_pid_kp_s6",
                                 "cfg_pid_kp_s7", "cfg_pid_kp_s8"
                             });
    copyFirstAvailableNumber("devFCKi", {
                                 "forcePidTuningKi",
                                 "cfg_pid_ki_s1", "cfg_pid_ki_s2",
                                 "cfg_pid_ki_s3", "cfg_pid_ki_s4",
                                 "cfg_pid_ki_s5", "cfg_pid_ki_s6",
                                 "cfg_pid_ki_s7", "cfg_pid_ki_s8"
                             });
    copyFirstAvailableNumber("devFCKd", {
                                 "forcePidTuningKd",
                                 "cfg_pid_kd_s1", "cfg_pid_kd_s2",
                                 "cfg_pid_kd_s3", "cfg_pid_kd_s4",
                                 "cfg_pid_kd_s5", "cfg_pid_kd_s6",
                                 "cfg_pid_kd_s7", "cfg_pid_kd_s8"
                             });
    copyFirstAvailableNumber("devFCIntegralTorqueLimitNm", {
                                 "forcePidTuningIntegralTorqueLimitNm",
                                 "cfg_integral_torque_limit_Nm"
                             });

    const QRadioButton* useLite = root ?
                root->findChild<QRadioButton*>(QStringLiteral("devUseLite")) : nullptr;
    const QJsonObject defaults = useLite && useLite->isChecked() ?
                liteForcePidDefaultWidgetValues() :
                builtInForcePidDefaultWidgetValues();
    QJsonObject completedValues;
    QStringList missingItems;
    QStringList invalidItems;
    QStringList unavailableItems;
    const QStringList names = forcePidAutoSaveWidgetNames();
    for(const QString& name : names){
        const QJsonValue defaultValue = defaults.value(name);
        QWidget* widget = root ? root->findChild<QWidget*>(name) : nullptr;
        if(defaultValue.isUndefined()){
            unavailableItems << QStringLiteral("%1（内置默认值未定义）").arg(name);
            continue;
        }
        if(!shouldPersistParameterWidget(widget) ||
                !applyForcePidJsonValueToWidget(widget, defaultValue)){
            unavailableItems << QStringLiteral("%1（默认值=%2）")
                                .arg(name, forcePidJsonValueText(defaultValue));
            continue;
        }

        completedValues.insert(name, forcePidWidgetJsonValue(widget));
        if(!source.contains(name)){
            missingItems << QStringLiteral("%1=%2")
                            .arg(name, forcePidJsonValueText(defaultValue));
            continue;
        }

        const QJsonValue suppliedValue = source.value(name);
        if(!applyForcePidJsonValueToWidget(widget, suppliedValue)){
            invalidItems << QStringLiteral("%1（文件值=%2，默认值=%3）")
                            .arg(name,
                                 forcePidJsonValueText(suppliedValue),
                                 forcePidJsonValueText(defaultValue));
            applyForcePidJsonValueToWidget(widget, defaultValue);
            continue;
        }
        completedValues.insert(name, forcePidWidgetJsonValue(widget));
    }

    if(warningMessage){
        *warningMessage = buildParameterValidationMessage(
                    QStringLiteral("力控参数"),
                    missingItems,
                    invalidItems,
                    unavailableItems);
    }
    return completedValues;
}

QString formatIsoDateTimeUs(qint64 wallClockUs)
{
    if(wallClockUs <= 0){
        return QStringLiteral("无有效时间戳");
    }
    const qint64 wallClockMs = wallClockUs / 1000;
    const qint64 usInSecond = ((wallClockUs % 1000000) + 1000000) % 1000000;
    return QStringLiteral("%1.%2")
            .arg(QDateTime::fromMSecsSinceEpoch(wallClockMs).toString(QStringLiteral("yyyy-MM-ddTHH:mm:ss")))
            .arg(usInSecond, 6, 10, QLatin1Char('0'));
}

bool hasFiniteValues(const std::vector<double>& values, int minSize = 0)
{
    if(static_cast<int>(values.size()) < minSize){
        return false;
    }
    for(double value : values){
        if(!std::isfinite(value)){
            return false;
        }
    }
    return true;
}

QString pvtTracePoseFilenameToken(const std::vector<double>& pose)
{
    if(!hasFiniteValues(pose, 6)){
        return QStringLiteral("pose_na");
    }

    QStringList parts;
    parts.reserve(6);
    for(int dim=0; dim<6; ++dim){
        QString valueText = QString::number(pose[dim], 'f', dim < 3 ? 1 : 4);
        valueText.replace(QLatin1Char('-'), QLatin1Char('m'));
        valueText.replace(QLatin1Char('.'), QLatin1Char('p'));
        parts << valueText;
    }
    return parts.join(QStringLiteral("_"));
}

bool hasFinitePoseMatrix(const std::vector<std::vector<double>>& values)
{
    if(values.empty() || values.front().size() < 6){
        return false;
    }
    for(const std::vector<double>& row : values){
        if(!hasFiniteValues(row, 6)){
            return false;
        }
    }
    return true;
}

std::vector<std::vector<double>> normalizedPoseMatrix(std::vector<std::vector<double>> values)
{
    if(!hasFinitePoseMatrix(values)){
        return {};
    }
    for(std::vector<double>& row : values){
        row.resize(6);
    }
    return values;
}

int poseTrajectoryPointCountForVisualization(
        const std::vector<std::vector<std::vector<std::vector<double>>>>& trajectory)
{
    if(trajectory.empty() ||
            trajectory.front().empty() ||
            trajectory.front().front().size() < 6 ||
            trajectory.front().front().front().empty()){
        return 0;
    }

    const int pointCount =
            static_cast<int>(trajectory.front().front().front().size());
    for(const auto& endTraj : trajectory){
        if(endTraj.empty() || endTraj.front().size() < 6){
            return 0;
        }
        for(int dim=0; dim<6; ++dim){
            if(static_cast<int>(endTraj.front()[dim].size()) != pointCount){
                return 0;
            }
        }
    }
    return pointCount;
}

std::vector<double> poseTrajectoryTimeAxisForVisualization(
        const std::vector<std::vector<std::vector<std::vector<double>>>>& trajectory,
        int pointCount,
        double fallbackStepSec)
{
    if(pointCount <= 0){
        return {};
    }

    if(!trajectory.empty() &&
            trajectory.front().size() > 3 &&
            !trajectory.front()[3].empty() &&
            static_cast<int>(trajectory.front()[3][0].size()) == pointCount &&
            hasFiniteValues(trajectory.front()[3][0], pointCount)){
        return trajectory.front()[3][0];
    }

    if(fallbackStepSec <= 0.0 || !std::isfinite(fallbackStepSec)){
        fallbackStepSec = 0.01;
    }
    std::vector<double> timeAxis(pointCount, 0.0);
    for(int i=0; i<pointCount; ++i){
        timeAxis[i] = i * fallbackStepSec;
    }
    return timeAxis;
}

int nearestPoseTrajectoryPointIndex(const std::vector<double>& timeAxis,
                                    double trajectoryTimeSec)
{
    if(timeAxis.empty() || !std::isfinite(trajectoryTimeSec)){
        return -1;
    }
    if(trajectoryTimeSec <= timeAxis.front()){
        return 0;
    }
    if(trajectoryTimeSec >= timeAxis.back()){
        return static_cast<int>(timeAxis.size()) - 1;
    }

    auto upperIt = std::lower_bound(timeAxis.begin(), timeAxis.end(), trajectoryTimeSec);
    if(upperIt == timeAxis.begin()){
        return 0;
    }
    if(upperIt == timeAxis.end()){
        return static_cast<int>(timeAxis.size()) - 1;
    }

    const int upperIndex = static_cast<int>(std::distance(timeAxis.begin(), upperIt));
    const int lowerIndex = upperIndex - 1;
    const double lowerError = std::abs(trajectoryTimeSec - timeAxis[lowerIndex]);
    const double upperError = std::abs(timeAxis[upperIndex] - trajectoryTimeSec);
    return upperError < lowerError ? upperIndex : lowerIndex;
}

std::vector<std::vector<std::vector<std::vector<double>>>> buildSingleEndTrajectoryFromPoseRows(
        const std::vector<std::vector<double>>& poseRows,
        const std::vector<double>& timeStamp)
{
    if(poseRows.empty()){
        return {};
    }

    const int pointCount = static_cast<int>(poseRows.size());
    std::vector<std::vector<std::vector<std::vector<double>>>> trajectory(1);
    trajectory[0].resize(4);
    for(int layer=0; layer<4; ++layer){
        trajectory[0][layer].assign(6, std::vector<double>(pointCount, 0.0));
    }

    for(int pointIndex=0; pointIndex<pointCount; ++pointIndex){
        if(poseRows[pointIndex].size() < 6){
            return {};
        }
        for(int dim=0; dim<6; ++dim){
            trajectory[0][0][dim][pointIndex] = poseRows[pointIndex][dim];
            if(static_cast<int>(timeStamp.size()) == pointCount){
                trajectory[0][3][dim][pointIndex] = timeStamp[pointIndex];
            }
        }
    }
    return trajectory;
}

qint64 jsonDateTimeToMs(const QJsonObject& object,
                        const QString& timestampKey,
                        const QString& isoKey)
{
    qint64 timestampMs = jsonValueToInt64(object.value(timestampKey), -1);
    if(timestampMs >= 0){
        return timestampMs;
    }

    QDateTime parsed = QDateTime::fromString(object.value(isoKey).toString(),
                                             Qt::ISODateWithMs);
    if(!parsed.isValid()){
        parsed = QDateTime::fromString(object.value(isoKey).toString(), Qt::ISODate);
    }
    return parsed.isValid() ? parsed.toMSecsSinceEpoch() : -1;
}

qint64 maxValidTimestampMs(std::initializer_list<qint64> timestamps)
{
    qint64 result = -1;
    for(qint64 timestamp : timestamps){
        if(timestamp >= 0 && timestamp > result){
            result = timestamp;
        }
    }
    return result;
}

void insertJsonTimestamp(QJsonObject& object,
                         const QString& timestampKey,
                         const QString& isoKey,
                         qint64 timestampMs)
{
    if(timestampMs < 0){
        return;
    }
    object.insert(timestampKey, timestampMs);
    object.insert(isoKey,
                  QDateTime::fromMSecsSinceEpoch(timestampMs)
                  .toString(Qt::ISODateWithMs));
}

qint64 cableHomeConfirmedTimestampFromRuntimeSnapshot(const QJsonObject& root)
{
    const QJsonObject zeroReference =
            root.value(QStringLiteral("zero_motor_home_reference")).toObject();
    const QJsonObject savedCurrentPose =
            root.value(QStringLiteral("saved_current_pose")).toObject();
    return maxValidTimestampMs({
                                   jsonDateTimeToMs(root,
                                                    QStringLiteral("cable_home_confirmed_at_ms"),
                                                    QStringLiteral("cable_home_confirmed_at")),
                                   jsonDateTimeToMs(zeroReference,
                                                    QStringLiteral("confirmed_at_ms"),
                                                    QStringLiteral("confirmed_at")),
                                   jsonDateTimeToMs(savedCurrentPose,
                                                    QStringLiteral("cable_home_confirmed_at_ms"),
                                                    QStringLiteral("cable_home_confirmed_at"))
                               });
}

qint64 timestampFromStampedSnapshotFileName(const QString& filePath,
                                            const QString& prefix)
{
    const QString fileName = QFileInfo(filePath).fileName();
    const QRegularExpression pattern(
                QStringLiteral("^%1_(\\d{8}_\\d{6})(?:_(\\d{3}))?\\.json$")
                .arg(QRegularExpression::escape(prefix)));
    const QRegularExpressionMatch match = pattern.match(fileName);
    if(!match.hasMatch()){
        return -1;
    }

    const QString millis = match.captured(2);
    const QString stamp = millis.isEmpty() ?
                match.captured(1) :
                QStringLiteral("%1_%2").arg(match.captured(1), millis);
    const QString format = millis.isEmpty() ?
                QStringLiteral("yyyyMMdd_HHmmss") :
                QStringLiteral("yyyyMMdd_HHmmss_zzz");
    const QDateTime timestamp = QDateTime::fromString(stamp, format);
    return timestamp.isValid() ? timestamp.toMSecsSinceEpoch() : -1;
}

qint64 stampedSnapshotFileNameTimestampMs(const QString& filePath)
{
    return maxValidTimestampMs({
                                   timestampFromStampedSnapshotFileName(
                                       filePath,
                                       QStringLiteral("zero_calibration")),
                                   timestampFromStampedSnapshotFileName(
                                       filePath,
                                       QStringLiteral("known_runtime_pose_reference"))
                               });
}

qint64 snapshotFileTimestampMs(const QString& filePath)
{
    qint64 timestampMs = stampedSnapshotFileNameTimestampMs(filePath);
    QFile file(filePath);
    if(!file.open(QIODevice::ReadOnly | QIODevice::Text)){
        return timestampMs;
    }

    QJsonParseError parseError;
    const QJsonDocument document = QJsonDocument::fromJson(file.readAll(), &parseError);
    file.close();
    if(parseError.error != QJsonParseError::NoError || !document.isObject()){
        return timestampMs;
    }

    const QJsonObject root = document.object();
    const QJsonObject savedCurrentPose =
            root.value(QStringLiteral("saved_current_pose")).toObject();
    const QJsonObject poseEstimate =
            root.value(QStringLiteral("pose_estimate")).toObject();
    const QJsonObject plannedTrajectory =
            root.value(QStringLiteral("planned_pose_trajectory")).toObject();
    timestampMs = maxValidTimestampMs({
                                          timestampMs,
                                          jsonDateTimeToMs(root,
                                                           QStringLiteral("saved_at_ms"),
                                                           QStringLiteral("saved_at")),
                                          jsonDateTimeToMs(root,
                                                           QStringLiteral("confirmed_at_ms"),
                                                           QStringLiteral("confirmed_at")),
                                          cableHomeConfirmedTimestampFromRuntimeSnapshot(root),
                                          jsonDateTimeToMs(savedCurrentPose,
                                                           QStringLiteral("updated_at_ms"),
                                                           QStringLiteral("updated_at")),
                                          jsonDateTimeToMs(poseEstimate,
                                                           QStringLiteral("updated_at_ms"),
                                                           QStringLiteral("updated_at")),
                                          jsonDateTimeToMs(plannedTrajectory,
                                                           QStringLiteral("updated_at_ms"),
                                                           QStringLiteral("updated_at"))
                                      });
    return timestampMs;
}

qint64 snapshotCandidateTimestampMs(const QString& filePath)
{
    qint64 timestampMs = stampedSnapshotFileNameTimestampMs(filePath);
    if(timestampMs >= 0){
        return timestampMs;
    }

    const QFileInfo fileInfo(filePath);
    if(fileInfo.exists() && fileInfo.lastModified().isValid()){
        return fileInfo.lastModified().toMSecsSinceEpoch();
    }
    return snapshotFileTimestampMs(filePath);
}

QStringList stampedSnapshotHistoryFilePaths(const QString& dirPath,
                                            const QString& prefix)
{
    QStringList paths;
    const QDir dir(dirPath);
    const QFileInfoList entries =
            dir.entryInfoList(QStringList()
                              << QStringLiteral("%1_*.json").arg(prefix),
                              QDir::Files,
                              QDir::Name);
    for(const QFileInfo& entry : entries){
        paths << QDir::cleanPath(entry.absoluteFilePath());
    }
    return paths;
}

QStringList sortedExistingSnapshotCandidates(const QStringList& rawPaths)
{
    struct CandidateEntry {
        QString path;
        qint64 timestampMs = -1;
        int order = 0;
    };

    std::vector<CandidateEntry> candidates;
    QStringList uniquePaths;
    for(const QString& rawPath : rawPaths){
        if(rawPath.isEmpty()){
            continue;
        }
        const QString cleanPath = QDir::cleanPath(rawPath);
        if(!uniquePaths.contains(cleanPath) && QFileInfo::exists(cleanPath)){
            uniquePaths << cleanPath;
            CandidateEntry entry;
            entry.path = cleanPath;
            entry.timestampMs = snapshotCandidateTimestampMs(cleanPath);
            entry.order = static_cast<int>(candidates.size());
            candidates.push_back(entry);
        }
    }

    std::stable_sort(candidates.begin(), candidates.end(),
                     [](const CandidateEntry& lhs, const CandidateEntry& rhs){
        if(lhs.timestampMs != rhs.timestampMs){
            return lhs.timestampMs > rhs.timestampMs;
        }
        return lhs.order < rhs.order;
    });

    QStringList paths;
    for(const CandidateEntry& candidate : candidates){
        paths << candidate.path;
    }
    return paths;
}

qint64 latestSnapshotTimestampMsForPrefix(const QString& dirPath,
                                          const QString& prefix,
                                          const QString& latestPath)
{
    qint64 timestampMs = -1;
    if(!latestPath.isEmpty()){
        timestampMs = snapshotFileTimestampMs(latestPath);
        if(timestampMs < 0){
            timestampMs = snapshotCandidateTimestampMs(latestPath);
        }
    }
    const QStringList historyPaths = stampedSnapshotHistoryFilePaths(dirPath, prefix);
    for(const QString& historyPath : historyPaths){
        timestampMs = maxValidTimestampMs({timestampMs, snapshotCandidateTimestampMs(historyPath)});
    }
    return timestampMs;
}

