void MainWindow::setupParameterFrameDialogs()
{
    if(!ui){
        return;
    }

    QDoubleSpinBox* workspaceWarningMarginSpin =
            ensureStructureWorkspaceWarningMarginUi(this);
    if(workspaceWarningMarginSpin){
        connect(workspaceWarningMarginSpin,
                QOverload<double>::of(&QDoubleSpinBox::valueChanged),
                this,
                [this](double){
            updateSafetyMonitorConfig();
        });
    }

    auto moveFrameToDialog = [this](QDialog*& dialog,
                                    QFrame* frame,
                                    QPushButton* openButton,
                                    const QString& title,
                                    const QSize& initialSize){
        if(!frame || !openButton){
            return;
        }

        if(!dialog){
            dialog = new QDialog(this);
            dialog->setObjectName(frame->objectName() + QStringLiteral("Dialog"));
            dialog->setWindowTitle(title);
            dialog->setModal(false);
            dialog->setAttribute(Qt::WA_DeleteOnClose, false);

            auto* dialogLayout = new QVBoxLayout(dialog);
            dialogLayout->setContentsMargins(8, 8, 8, 8);
            dialogLayout->setSpacing(8);

            if(QWidget* oldParent = frame->parentWidget()){
                if(QLayout* oldLayout = oldParent->layout()){
                    oldLayout->removeWidget(frame);
                }
            }
            dialogLayout->addWidget(frame);
            frame->setVisible(true);
            dialog->resize(dialog->sizeHint().expandedTo(initialSize));
        }

        openButton->setToolTip(QStringLiteral("打开%1配置窗口").arg(title));
        connect(openButton, &QPushButton::clicked, this, [dialog, frame](){
            if(!dialog || !frame){
                return;
            }
            frame->setVisible(true);
            dialog->show();
            dialog->raise();
            dialog->activateWindow();
        });
    };

    moveFrameToDialog(structureParamsDialog,
                      ui->frame_46,
                      ui->openStructureParamsDialogButton,
                      QStringLiteral("结构参数"),
                      QSize(520, 180));
    moveFrameToDialog(endParamsDialog,
                      ui->frame_6,
                      ui->openEndParamsDialogButton,
                      QStringLiteral("末端参数"),
                      QSize(900, 420));

    if(ui->openDataVisualizationTabButton){
        connect(ui->openDataVisualizationTabButton, &QPushButton::clicked, this, [this](){
            if(ui && ui->tabWidget && ui->dataVizTab){
                ui->tabWidget->setCurrentWidget(ui->dataVizTab);
            }
        });
    }
    if(ui->openRuntimeDiagnosticsTabButton){
        connect(ui->openRuntimeDiagnosticsTabButton, &QPushButton::clicked, this, [this](){
            if(ui && ui->tabWidget && ui->runtimeDiagnosticsTab){
                ui->tabWidget->setCurrentWidget(ui->runtimeDiagnosticsTab);
            }
        });
    }
}

void MainWindow::initializeConnectionStatusUi()
{
    if(connectionStatusGroupBox || !ui){
        return;
    }

    connectionStatusGroupBox = ui->connectionStatusGroupBox;
    connectionControllerStatusLabel = ui->connectionControllerStatusLabel;
    connectionAxisStatusLabels = {
        ui->connectionAxisStatusLabel_1,
        ui->connectionAxisStatusLabel_2,
        ui->connectionAxisStatusLabel_3,
        ui->connectionAxisStatusLabel_4,
        ui->connectionAxisStatusLabel_5,
        ui->connectionAxisStatusLabel_6,
        ui->connectionAxisStatusLabel_7,
        ui->connectionAxisStatusLabel_8,
        ui->connectionAxisStatusLabel_9,
        ui->connectionAxisStatusLabel_10,
        ui->connectionAxisStatusLabel_11,
        ui->connectionAxisStatusLabel_12
    };
    connectionSensorStatusLabels = {
        ui->connectionSensorStatusLabel_1,
        ui->connectionSensorStatusLabel_2
    };

    if(!connectionStatusGroupBox || !connectionControllerStatusLabel){
        connectionAxisStatusLabels.clear();
        connectionSensorStatusLabels.clear();
        return;
    }

    if(QLabel* legendLabel = ui->connectionStatusLegendLabel){
        legendLabel->setText(QStringLiteral("绿=连接且使能  黄=连接且失能  灰=断开  红=异常"));
    }

    for(QLabel* label : connectionAxisStatusLabels){
        if(!label){
            connectionAxisStatusLabels.clear();
            connectionSensorStatusLabels.clear();
            return;
        }
    }
    for(QLabel* label : connectionSensorStatusLabels){
        if(!label){
            connectionAxisStatusLabels.clear();
            connectionSensorStatusLabels.clear();
            return;
        }
    }

    refreshConnectionStatusUi(true);
}

void MainWindow::setConnectionStatusIndicator(QLabel* label,
                                              const QString& title,
                                              HardwareInterface::ConnectionState state,
                                              const QString& tooltip,
                                              const QString& stateTextOverride)
{
    if(!label){
        return;
    }

    const QString stateText = stateTextOverride.isEmpty() ?
                connectionStateDisplayText(state) :
                stateTextOverride;
    const QString text = QStringLiteral("%1\n%2").arg(title, stateText);
    const QString style = connectionStateStyle(state);

    if(label->text() != text){
        label->setText(text);
    }
    if(label->styleSheet() != style){
        label->setStyleSheet(style);
    }
    if(label->toolTip() != tooltip){
        label->setToolTip(tooltip);
    }
}

void MainWindow::refreshConnectionStatusUi(bool force)
{
    if(!connectionStatusGroupBox || !ui ||
            !connectionControllerStatusLabel ||
            connectionAxisStatusLabels.empty() ||
            connectionSensorStatusLabels.empty()){
        return;
    }

    if(guiRefreshProfile == GuiRefreshProfile::EndpointRemoteFrozen){
        // Full connection diagnostics enqueue controller and per-axis SDK
        // queries on HardwareThread.  Keep the existing indicators unchanged
        // during endpoint remote; the safety/control paths use same-frame
        // Trace state, and the normal one-second refresh resumes on exit.
        refreshSingleMotorEnableStateUi();
        return;
    }

    const qint64 nowMs = QDateTime::currentMSecsSinceEpoch();
    if(!force &&
            lastConnectionStatusUiRefreshMs >= 0 &&
            (nowMs - lastConnectionStatusUiRefreshMs) < kConnectionStatusRefreshIntervalMs){
        return;
    }

    refreshAxisRuntimeCounts();

    const int axisCount = static_cast<int>(connectionAxisStatusLabels.size());
    const int sensorCount = static_cast<int>(connectionSensorStatusLabels.size());

    const bool liteSelectedOnlyDiagnostics =
            isLiteTemplateActive() &&
            !runtimeState.systemRunning &&
            hardwareInterface.isLSConnected();
    HardwareInterface::ConnectionDiagnostics diagnostics;
    int liteSelectedAxis = -1;
    bool liteSelectedAxisAvailable = false;
    int liteSelectedSensor = -1;
    bool liteSelectedSensorPolled = false;
    if(liteSelectedOnlyDiagnostics){
        diagnostics.controller = liteCommissioningControllerDiagnosticsValid ?
                    liteCommissioningControllerDiagnostics :
                    HardwareInterface::ConnectionItemDiagnostics();
        diagnostics.motorAxes.resize(std::max(axisCount, 0));
        diagnostics.forceSensors.resize(std::max(sensorCount, 0));
        liteSelectedAxis = selectedLiteCommissioningAxis();
        liteSelectedAxisAvailable =
                liteCommissioningAxisAvailableInSelectedTopology(liteSelectedAxis);
        if(liteSelectedAxis >= 0 &&
                liteSelectedAxis < axisCount &&
                liteSelectedAxisAvailable){
            if(liteSelectedAxis < static_cast<int>(liteAxisCommissioningStates.size())){
                const LiteAxisCommissioningState& cachedAxis =
                        liteAxisCommissioningStates[liteSelectedAxis];
                HardwareInterface::ConnectionItemDiagnostics axis;
                axis.hardwareAxis =
                        liteSelectedAxis < static_cast<int>(axisMotorHardwareAxisVec.size()) &&
                        axisMotorHardwareAxisVec[liteSelectedAxis] ?
                            axisMotorHardwareAxisVec[liteSelectedAxis]->value() : -1;
                axis.stateMachine = cachedAxis.stateMachine;
                axis.busState = cachedAxis.busState;
                axis.errorCode = cachedAxis.errorCode;
                axis.apiResult = cachedAxis.apiResult;
                axis.state = cachedAxis.online ?
                            (cachedAxis.enabled ?
                                 HardwareInterface::ConnectionState::Connected :
                                 HardwareInterface::ConnectionState::Disabled) :
                            ((cachedAxis.apiResult != 0 || cachedAxis.errorCode != 0) ?
                                 HardwareInterface::ConnectionState::Fault :
                                 HardwareInterface::ConnectionState::Disconnected);
                diagnostics.motorAxes[liteSelectedAxis] = axis;
            }
            if(liteSelectedAxis < static_cast<int>(axisSensorIndexVec.size()) &&
                    axisSensorIndexVec[liteSelectedAxis]){
                liteSelectedSensor = axisSensorIndexVec[liteSelectedAxis]->value();
            }
        }
    }
    else{
        diagnostics = hardwareInterface.connectionDiagnostics();
    }

    QString controllerTooltip = QStringLiteral("主站状态: %1\n错误码: %2")
            .arg(diagnostics.controller.busState)
            .arg(diagnostics.controller.errorCode);
    if(!ui->devUseLS->isChecked() &&
            diagnostics.controller.state == HardwareInterface::ConnectionState::Disconnected){
        controllerTooltip = QStringLiteral("当前未启用雷赛控制卡。\n%1").arg(controllerTooltip);
    }
    if(diagnostics.controller.apiResult != 0){
        controllerTooltip += QStringLiteral("\n接口返回: %1").arg(diagnostics.controller.apiResult);
    }
    setConnectionStatusIndicator(connectionControllerStatusLabel,
                                 QStringLiteral("控制卡"),
                                 diagnostics.controller.state,
                                 controllerTooltip);

    for(int i = 0; i < axisCount; ++i){
        HardwareInterface::ConnectionState state = HardwareInterface::ConnectionState::Disconnected;
        const QString axisDisplayName = motorAxisDisplayName(i);
        QString tooltip;
        QString stateText;
        if(liteSelectedOnlyDiagnostics && i != liteSelectedAxis){
            tooltip = QStringLiteral("Lite 单轴调试中未轮询该电机。");
            stateText = QStringLiteral("未轮询");
        }
        else if(liteSelectedOnlyDiagnostics && !liteSelectedAxisAvailable){
            tooltip = QStringLiteral("当前临时7轴Trace拓扑禁止访问硬件轴7。");
            stateText = QStringLiteral("拓扑禁用");
        }
        else{
            tooltip = QStringLiteral("%1当前未配置为雷赛电机。").arg(axisDisplayName);
            stateText = QStringLiteral("断开");
        }

        if(i < static_cast<int>(diagnostics.motorAxes.size()) &&
                (!liteSelectedOnlyDiagnostics ||
                 (i == liteSelectedAxis && liteSelectedAxisAvailable))){
            const HardwareInterface::ConnectionItemDiagnostics& axis = diagnostics.motorAxes[i];
            state = axis.state;

            QStringList details;
            details << QStringLiteral("电机: %1").arg(axisDisplayName);
            if(axis.hardwareAxis >= 0){
                details << QStringLiteral("控制卡轴: %1").arg(axis.hardwareAxis);
            }
            if(axis.slaveAddress > 0){
                details << QStringLiteral("从站地址: %1").arg(axis.slaveAddress);
            }
            if(axis.subSlaveAddress > 0){
                details << QStringLiteral("子从站: %1").arg(axis.subSlaveAddress);
            }
            if(axis.busState >= 0){
                details << QStringLiteral("从站状态: %1").arg(axis.busState);
            }
            if(axis.stateMachine >= 0){
                details << QStringLiteral("状态机: %1").arg(axis.stateMachine);
                details << QStringLiteral("伺服使能: %1")
                           .arg(axis.stateMachine == 4 ? QStringLiteral("是") : QStringLiteral("否"));
            }
            details << QStringLiteral("状态字: 0x%1")
                       .arg(QString::number(static_cast<quint32>(axis.statusWord), 16).toUpper());
            details << QStringLiteral("停止原因: %1").arg(axis.stopReason);
            if(axis.stopReasonApiResult != 0){
                details << QStringLiteral("停止原因读取返回: %1").arg(axis.stopReasonApiResult);
            }
            details << QStringLiteral("驱动器错误码: %1")
                       .arg(formatMotorDriveErrorCodeHex(axis.errorCode));
            if(axis.apiResult != 0){
                details << QStringLiteral("接口返回: %1").arg(axis.apiResult);
            }
            tooltip = details.join(QLatin1Char('\n'));

            if(state == HardwareInterface::ConnectionState::Connected){
                stateText = QStringLiteral("连接且使能");
            }
            else if(state == HardwareInterface::ConnectionState::Disabled){
                stateText = QStringLiteral("连接且失能");
            }
            else if(state == HardwareInterface::ConnectionState::Fault){
                stateText = QStringLiteral("异常");
            }
        }

        setConnectionStatusIndicator(connectionAxisStatusLabels[i],
                                     axisDisplayName,
                                     state,
                                     tooltip,
                                     stateText);
    }

    for(int i = 0; i < sensorCount; ++i){
        HardwareInterface::ConnectionState state = HardwareInterface::ConnectionState::Disconnected;
        QString tooltip = liteSelectedOnlyDiagnostics && i != liteSelectedSensor ?
                    QStringLiteral("Lite 单轴调试中未轮询该张力通道。") :
                    QStringLiteral("张力通道%1当前未配置。").arg(i + 1);

        if(i < static_cast<int>(diagnostics.forceSensors.size()) &&
                (!liteSelectedOnlyDiagnostics ||
                 (i == liteSelectedSensor && liteSelectedSensorPolled))){
            const HardwareInterface::ConnectionItemDiagnostics& sensor = diagnostics.forceSensors[i];
            state = sensor.state;

            QStringList details;
            details << QStringLiteral("传感器通道: %1").arg(i + 1);
            if(sensor.state == HardwareInterface::ConnectionState::Disabled){
                details << QStringLiteral("在线速度 Trace 配置已主动停用该通道");
            }
            else if(sensor.apiResult != 0){
                details << QStringLiteral("Trace读取异常: %1").arg(sensor.apiResult);
            }
            else{
                details << QStringLiteral("Trace读取正常");
            }
            tooltip = details.join(QLatin1Char('\n'));
        }

        setConnectionStatusIndicator(connectionSensorStatusLabels[i],
                                     QStringLiteral("力%1").arg(i + 1),
                                     state,
                                     tooltip);
    }

    refreshSingleMotorEnableStateUi();
    lastConnectionStatusUiRefreshMs = nowMs;
}

void MainWindow::refreshPrimaryOperationUiState(const RobotStateSnapshot& robotState)
{
    auto setTextIfChanged = [](QAbstractButton* button, const QString& text){
        if(button && button->text() != text){
            button->setText(text);
        }
    };
    auto setEnabledIfChanged = [](QWidget* widget, bool enabled){
        if(widget && widget->isEnabled() != enabled){
            widget->setEnabled(enabled);
        }
    };
    auto setToolTipIfChanged = [](QWidget* widget, const QString& text){
        if(widget && widget->toolTip() != text){
            widget->setToolTip(text);
        }
    };
    auto setLabelTextIfChanged = [](QLabel* label, const QString& text){
        if(label && label->text() != text){
            label->setText(text);
        }
    };
    auto setLabelStyleIfChanged = [](QLabel* label, const QString& style){
        if(label && label->styleSheet() != style){
            label->setStyleSheet(style);
        }
    };

    QString pauseButtonText = QStringLiteral("暂停");
    bool pauseEnabled = true;
    QString servoHoldButtonText = runtimeState.servoHoldActive ?
                QStringLiteral("解除抱闸") :
                QStringLiteral("抱闸");
    QString servoHoldToolTip = runtimeState.servoHoldActive ?
                QStringLiteral("当前处于软件抱闸保持状态（伺服失能，不是真实机械抱闸）。点击后将重新使能非直线模组电机，直线模组保持失能。") :
                QStringLiteral("软件保持功能，不是真实机械抱闸。点击后会先停止并等待停稳，再失能所有电机；再次点击只重新使能非直线模组电机，直线模组保持失能。紧急情况请使用“急停”。");
    bool servoHoldEnabled = true;
    const bool liteCommissioning =
            isLiteTemplateActive() &&
            !runtimeState.systemRunning &&
            runtimeState.hardwareRunState != HardwareRunState::Disconnected;
    QString stateText = QStringLiteral("主控状态：待命");
    QString stateStyle = QStringLiteral(
                "QLabel { color: #334155; background: #f8fafc; border: 1px solid #cbd5e1; "
                "border-radius: 4px; padding: 6px 8px; font-weight: 600; }");
    const bool mainPauseSpeedZeroActive =
            runtimeState.mainPauseSpeedZeroActive &&
            controlBoxSpeedZeroPvtReturnState.valid;
    const bool mainPauseResumeRequested =
            mainPauseSpeedZeroActive &&
            (controlBoxSpeedZeroPvtReturnState.speedZeroResumeRequested ||
             controlBoxSpeedZeroPvtReturnState.speedZeroResumeStartInProgress);

    if(runtimeState.safetyFaultLatched){
        stateText = QStringLiteral("主控状态：安全锁存");
        stateStyle = QStringLiteral(
                    "QLabel { color: #991b1b; background: #fee2e2; border: 1px solid #fca5a5; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(mainPauseSpeedZeroActive){
        pauseButtonText = QStringLiteral("继续");
        pauseEnabled = !mainPauseResumeRequested;
        stateText = controlBoxSpeedZeroPvtReturnState.speedZeroResumeStartInProgress ?
                    QStringLiteral("主控状态：速度置零续跑正在启动") :
                    (mainPauseResumeRequested ?
                    QStringLiteral("主控状态：速度置零续跑等待回点完成") :
                    QStringLiteral("主控状态：速度置零已暂停"));
        stateStyle = QStringLiteral(
                    "QLabel { color: #92400e; background: #fef3c7; border: 1px solid #fcd34d; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(robotState.positionMotionState == PositionMotionState::PausedPvt){
        pauseButtonText = QStringLiteral("继续");
        pauseEnabled = true;
        stateText = QStringLiteral("主控状态：位置轨迹已暂停");
        stateStyle = QStringLiteral(
                    "QLabel { color: #92400e; background: #fef3c7; border: 1px solid #fcd34d; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(robotState.forceMotionState == ForceMotionState::HybridPoseForceTrajectory){
        pauseEnabled = true;
        stateText = QStringLiteral("主控状态：力位混合轨迹执行中");
        stateStyle = QStringLiteral(
                    "QLabel { color: #6d28d9; background: #f3e8ff; border: 1px solid #d8b4fe; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(robotState.positionMotionState == PositionMotionState::ExecutingPvt){
        pauseEnabled = true;
        stateText = QStringLiteral("主控状态：位置轨迹运行中");
        stateStyle = QStringLiteral(
                    "QLabel { color: #166534; background: #dcfce7; border: 1px solid #86efac; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(robotState.positionMotionState == PositionMotionState::ExecutingOnlineVelocity){
        pauseEnabled = true;
        stateText = QStringLiteral("主控状态：八轴在线速度轨迹运行中");
        stateStyle = QStringLiteral(
                    "QLabel { color: #075985; background: #e0f2fe; border: 1px solid #7dd3fc; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(robotState.positionMotionState == PositionMotionState::Simulating){
        stateText = QStringLiteral("主控状态：轨迹仿真中");
        stateStyle = QStringLiteral(
                    "QLabel { color: #1d4ed8; background: #dbeafe; border: 1px solid #93c5fd; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(robotState.forceMotionState == ForceMotionState::HybridPoseForceReady){
        stateText = QStringLiteral("主控状态：力位混合准备状态");
        stateStyle = QStringLiteral(
                    "QLabel { color: #5b21b6; background: #ede9fe; border: 1px solid #c4b5fd; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(robotState.forceMotionState == ForceMotionState::DirectForceControl){
        stateText = QStringLiteral("主控状态：实时力控运行中");
        stateStyle = QStringLiteral(
                    "QLabel { color: #166534; background: #dcfce7; border: 1px solid #86efac; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(runtimeState.servoHoldActive){
        pauseEnabled = false;
        stateText = QStringLiteral("主控状态：软件抱闸保持中（伺服失能）");
        stateStyle = QStringLiteral(
                    "QLabel { color: #075985; background: #e0f2fe; border: 1px solid #7dd3fc; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(liteCommissioning){
        stateText = QStringLiteral("主控状态：Lite 单轴调试（整机未就绪）");
        stateStyle = QStringLiteral(
                    "QLabel { color: #92400e; background: #fff7ed; border: 1px solid #fdba74; "
                    "border-radius: 4px; padding: 6px 8px; font-weight: 700; }");
    }
    else if(robotState.systemRunning){
        stateText = QStringLiteral("主控状态：系统就绪");
    }
    else if(robotState.lsConnected){
        stateText = QStringLiteral("主控状态：已连接待上电");
    }

    const qint64 nowMs = QDateTime::currentMSecsSinceEpoch();
    if(primaryOperationFeedbackExpireMs > nowMs && !primaryOperationFeedbackText.isEmpty()){
        stateText = primaryOperationFeedbackText;
        stateStyle = primaryOperationFeedbackStyle;
    }
    else if(primaryOperationFeedbackExpireMs > 0 && nowMs >= primaryOperationFeedbackExpireMs){
        primaryOperationFeedbackExpireMs = 0;
        primaryOperationFeedbackText.clear();
        primaryOperationFeedbackStyle.clear();
    }

    if(liteCommissioning){
        pauseEnabled = false;
        servoHoldEnabled = false;
        servoHoldToolTip = QStringLiteral("Lite 单轴调试中禁止使用整机软件抱闸，请在调试页停止并失能当前轴。");
    }
    setTextIfChanged(ui->mainPauseSwitch, pauseButtonText);
    setEnabledIfChanged(ui->mainPauseSwitch, pauseEnabled);
    setTextIfChanged(ui->mainServoHoldSwitch, servoHoldButtonText);
    setEnabledIfChanged(ui->mainServoHoldSwitch, servoHoldEnabled);
    setToolTipIfChanged(ui->mainServoHoldSwitch, servoHoldToolTip);
    setLabelTextIfChanged(ui->mainMotionStateLabel, stateText);
    setLabelStyleIfChanged(ui->mainMotionStateLabel, stateStyle);
}

QString MainWindow::installationDataRootDirPath() const
{
    return RuntimePathUtils::dataRootDirectory();
}

bool MainWindow::initializeInstallationDataStorage(QString* errorMessage)
{
    if(errorMessage){
        errorMessage->clear();
    }

    const QString dataRoot = installationDataRootDirPath();
    if(!QDir().mkpath(dataRoot)){
        if(errorMessage){
            *errorMessage = dataRoot;
        }
        return false;
    }
    for(const QString& directoryName : kInstallationDataSubdirectories){
        const QString directoryPath = QDir(dataRoot).filePath(directoryName);
        if(!QDir().mkpath(directoryPath)){
            if(errorMessage){
                *errorMessage = directoryPath;
            }
            return false;
        }
    }

    QStringList legacyRoots;
    legacyRoots << QCoreApplication::applicationDirPath();
    const QString sourceRoot = QStringLiteral(G302_SOURCE_DIR);
    if(QFileInfo(sourceRoot).isDir() && !legacyRoots.contains(sourceRoot)){
        legacyRoots << sourceRoot;
    }

    int copiedFileCount = 0;
    QStringList migrationErrors;
    for(const QString& legacyRoot : legacyRoots){
        if(legacyRoot.isEmpty() || sameDirectoryPath(legacyRoot, dataRoot)){
            continue;
        }
        for(const QString& directoryName : kLegacyMigratedDataSubdirectories){
            copyMissingDirectoryTree(QDir(legacyRoot).filePath(directoryName),
                                     QDir(dataRoot).filePath(directoryName),
                                     &copiedFileCount,
                                     &migrationErrors);
        }
    }
    if(copiedFileCount > 0){
        qInfo().noquote() << QStringLiteral("已将 %1 个旧版运行数据文件迁移至 %2")
                              .arg(copiedFileCount)
                              .arg(dataRoot);
    }
    if(!migrationErrors.isEmpty()){
        qWarning().noquote() << QStringLiteral("部分旧版运行数据未迁移：%1")
                                 .arg(migrationErrors.join(QStringLiteral("；")));
    }
    return true;
}

void MainWindow::openInstallationDataFolder()
{
    QString errorMessage;
    const QString dataRoot = installationDataRootDirPath();
    if(!initializeInstallationDataStorage(&errorMessage)){
        displayInfo(QStringLiteral("错误：无法打开运行数据目录 %1")
                    .arg(errorMessage).toStdString(), "error");
        return;
    }
    if(!QDesktopServices::openUrl(QUrl::fromLocalFile(dataRoot))){
        displayInfo(QStringLiteral("错误：无法在资源管理器中打开运行数据目录 %1")
                    .arg(dataRoot).toStdString(), "error");
    }
}

