MainWindow::RunMode MainWindow::selectedRunModeFromUi() const{
    if(ui->runModeRealtimeRadio && ui->runModeRealtimeRadio->isChecked()){
        return RunMode::RealtimeTrajectory;
    }
    if(ui->runModeOnlineVelocityRadio && ui->runModeOnlineVelocityRadio->isChecked()){
        return RunMode::OnlineVelocityControl;
    }
    if(ui->runModeSimulationRadio && ui->runModeSimulationRadio->isChecked()){
        return RunMode::SimulationCalculation;
    }
    return RunMode::ProgramControl;
}

QString MainWindow::runModeDisplayName(RunMode mode) const{
    switch(mode){
    case RunMode::ProgramControl:
        return kRunModeProgram;
    case RunMode::RealtimeTrajectory:
        return kRunModeRealtime;
    case RunMode::OnlineVelocityControl:
        return kRunModeOnlineVelocity;
    case RunMode::SimulationCalculation:
        return kRunModeSimulation;
    }
    return kRunModeProgram;
}

void MainWindow::setProgramControlPvtPlanningTimingLabel(const QString& text,
                                                         const QString& tooltip)
{
    if(!kShowProgramControlPvtPlanningTiming){
        return;
    }

    if(ui && ui->programControlPvtPlanningValueLabel &&
            ui->programControlPvtPlanningValueLabel->text() != text){
        ui->programControlPvtPlanningValueLabel->setText(text);
    }
    if(!tooltip.isEmpty()){
        if(ui && ui->programControlPvtPlanningValueLabel){
            ui->programControlPvtPlanningValueLabel->setToolTip(tooltip);
        }
        if(ui && ui->programControlPvtPlanningTitleLabel){
            ui->programControlPvtPlanningTitleLabel->setToolTip(tooltip);
        }
    }
}

void MainWindow::beginProgramControlPvtPlanningTiming()
{
    if(runtimeState.runMode != RunMode::ProgramControl){
        return;
    }

    programControlPvtPlanningTimer.start();
    programControlPvtPlanningTimingActive = true;
    lastProgramControlPvtPlanningElapsedMs = -1.0;
    setProgramControlPvtPlanningTimingLabel(
                QStringLiteral("规划中..."),
                QStringLiteral("从程序控制参数确定后开始计时，到软件计算出本次 PVT 表数据为止；不包含控制卡下发和运动启动时间。"));
}

void MainWindow::finishProgramControlPvtPlanningTiming(int pvtPointCount,
                                                       int pvtAxisCount,
                                                       int sourceStartPointIndex)
{
    if(!programControlPvtPlanningTimingActive ||
            !programControlPvtPlanningTimer.isValid()){
        return;
    }

    const double elapsedMs =
            static_cast<double>(programControlPvtPlanningTimer.nsecsElapsed()) / 1000000.0;
    programControlPvtPlanningTimingActive = false;
    lastProgramControlPvtPlanningElapsedMs = elapsedMs;
    if(kEnableSessionRecordPvtControlCycleDiagnostics){
        captureSessionRecordingPvtControlCycleTiming(
                    pvtPointCount,
                    pvtAxisCount,
                    elapsedMs,
                    sourceStartPointIndex);
    }

    const QString elapsedText = elapsedMs >= 10000.0 ?
                QStringLiteral("%1 s").arg(elapsedMs / 1000.0, 0, 'f', 3) :
                QStringLiteral("%1 ms").arg(elapsedMs, 0, 'f', 3);
    const QString tooltip =
            QStringLiteral("本次程序控制从参数确定后到软件生成 PVT 表耗时 %1；PVT 表点数 %2，控制电机数 %3。不包含控制卡下发和运动启动时间。")
            .arg(elapsedText)
            .arg(pvtPointCount)
            .arg(pvtAxisCount);
    setProgramControlPvtPlanningTimingLabel(elapsedText, tooltip);
    if(kShowProgramControlPvtPlanningTiming){
        displayInfo(QStringLiteral("程序控制 PVT 表生成耗时：%1，点数%2，控制电机数%3（不含控制卡下发）")
                    .arg(elapsedText)
                    .arg(pvtPointCount)
                    .arg(pvtAxisCount)
                    .toStdString());
    }
}

void MainWindow::cancelProgramControlPvtPlanningTiming(const QString& reason)
{
    if(!programControlPvtPlanningTimingActive){
        return;
    }

    programControlPvtPlanningTimingActive = false;
    pendingPvtControlCycleRecordValid = false;
    lastProgramControlPvtPlanningElapsedMs = -1.0;
    const QString tooltip = reason.isEmpty() ?
                QStringLiteral("本次程序控制未生成 PVT 表。") :
                QStringLiteral("本次程序控制未生成 PVT 表：%1").arg(reason);
    setProgramControlPvtPlanningTimingLabel(QStringLiteral("未生成"), tooltip);
}

