bool MainWindow::udpPlatformAtReceiveHomePose() const
{
    std::vector<double> actualPose;
    if(!currentEstimatedEndPose(actualPose, 1000)){
        return false;
    }
    return isPoseNearUdpPlatformCenter(actualPose);
}

void MainWindow::clearUdpReturnHomeState()
{
    udpReturnHomePending = false;
    udpReturnHomeInProgress = false;
    udpReturnHomeFallbackStartPose.clear();
}

bool MainWindow::armUdpReturnHomeAfterTrajectory(const QVector<QVector<double>>& trajectoryPoints)
{
    udpReturnHomePending = false;
    udpReturnHomeInProgress = false;
    udpReturnHomeFallbackStartPose.clear();
    if(trajectoryPoints.isEmpty()){
        return false;
    }

    const QVector<double>& lastPoint = trajectoryPoints.back();
    if(lastPoint.size() != 7){
        displayInfo("警告：UDP轨迹末点格式无效，无法登记后置回中动作", "warning");
        return false;
    }

    std::vector<double> endPose(6, 0.0);
    for(int dim=0; dim<6; ++dim){
        endPose[dim] = lastPoint[dim + 1];
    }
    if(!hasFiniteValues(endPose, 6)){
        displayInfo("警告：UDP轨迹末点包含非有限数值，无法登记后置回中动作", "warning");
        return false;
    }

    if(isPoseNearUdpPlatformCenter(endPose)){
        displayInfo("UDP轨迹末点已在UDP中位附近，本轮不需要后置回中");
        return true;
    }

    udpReturnHomePending = true;
    udpReturnHomeFallbackStartPose = endPose;
    displayInfo(QStringLiteral("UDP轨迹已登记后置回中动作：轨迹完成后将从末点 [%1, %2, %3, %4, %5, %6] 规划到 UDP 中位 [0, 0, 700, 0, 0, 0]")
                .arg(endPose[0], 0, 'f', 3)
                .arg(endPose[1], 0, 'f', 3)
                .arg(endPose[2], 0, 'f', 3)
                .arg(endPose[3], 0, 'f', 6)
                .arg(endPose[4], 0, 'f', 6)
                .arg(endPose[5], 0, 'f', 6)
                .toStdString());
    return true;
}

bool MainWindow::startUdpReturnHomeTrajectory()
{
    if(!udpReturnHomePending){
        return false;
    }
    if(udpReturnHomeInProgress){
        displayInfo("UDP回中轨迹已在启动或执行中，忽略重复请求", "warning");
        return false;
    }

    std::vector<double> startPose;
    if(!currentEstimatedEndPose(startPose, 1000) ||
            startPose.size() < 6 ||
            !hasFiniteValues(startPose, 6)){
        if(hasFiniteValues(udpReturnHomeFallbackStartPose, 6)){
            startPose.assign(udpReturnHomeFallbackStartPose.begin(),
                             udpReturnHomeFallbackStartPose.begin() + 6);
        }
    }

    if(startPose.size() < 6 || !hasFiniteValues(startPose, 6)){
        displayInfo("错误：UDP后置回中启动失败，无法获取当前位姿或UDP轨迹末点位姿", "error");
        return false;
    }

    if(isPoseNearUdpPlatformCenter(startPose)){
        clearUdpReturnHomeState();
        updateUdpStatusPayload();
        if(udpCommWorker && udpRealtimeBridgeActive && udpV9PlatformFeedbackEnabled()){
            QMetaObject::invokeMethod(udpCommWorker,
                                      "sendStatusNow",
                                      Qt::QueuedConnection);
        }
        displayInfo("UDP后置回中跳过：当前位姿已在UDP中位附近");
        return true;
    }

    const bool keepV9FeedbackActive = udpRealtimeBridgeActive && udpV9PlatformFeedbackEnabled();
    if(runtimeState.runMode != RunMode::ProgramControl){
        setRunMode(RunMode::ProgramControl, false);
    }
    if(keepV9FeedbackActive && !udpRealtimeBridgeActive){
        startUdpForRealtimeMode();
    }

    useTrajFile = false;
    trajFilePreserveImportedTimeStep = false;
    trajFileOfflineTraj.clear();
    trajFileSegmentRanges.clear();
    resetTrajectoryFileProgramBatchState();
    if(ui->PostrajMode &&
            normalizePoseTrajectoryModeName(ui->PostrajMode->currentText()) != kPoseTrajStraight){
        ui->PostrajMode->setCurrentText(kPoseTrajStraight);
    }

    const std::vector<double> centerPose = udpPlatformCenterPose();
    const double uiRxOffsetRad = positionModeUiRxOffsetRad();
    const std::vector<double> startUiPose =
            platformPoseToPositionModeUiPose(
                std::vector<double>(startPose.begin(), startPose.begin() + 6),
                uiRxOffsetRad);
    const std::vector<double> centerUiPose =
            platformPoseToPositionModeUiPose(centerPose, uiRxOffsetRad);
    ui->mainPosModeTargetStartPx->setValue(startUiPose[0]);
    ui->mainPosModeTargetStartPy->setValue(startUiPose[1]);
    ui->mainPosModeTargetStartPz->setValue(startUiPose[2]);
    ui->mainPosModeTargetStartRx->setValue(startUiPose[3]);
    ui->mainPosModeTargetStartRy->setValue(startUiPose[4]);
    ui->mainPosModeTargetStartRz->setValue(startUiPose[5]);
    ui->mainPosModeTargetEndPx->setValue(centerUiPose[0]);
    ui->mainPosModeTargetEndPy->setValue(centerUiPose[1]);
    ui->mainPosModeTargetEndPz->setValue(centerUiPose[2]);
    ui->mainPosModeTargetEndRx->setValue(centerUiPose[3]);
    ui->mainPosModeTargetEndRy->setValue(centerUiPose[4]);
    ui->mainPosModeTargetEndRz->setValue(centerUiPose[5]);

    const double durationSec = estimateUdpReturnHomeDurationSec(startPose);
    ui->mainPosModeTargetRunTime->setValue(durationSec);
    if(ui->mainPosModeTargetStepTime){
        ui->mainPosModeTargetStepTime->setValue(kUdpReturnHomeDefaultStepSec * 1000.0);
    }
    updatePoseInputUiState();

    udpReturnHomeInProgress = true;
    updateUdpStatusPayload();
    if(keepV9FeedbackActive && udpCommWorker && udpRealtimeBridgeActive){
        QMetaObject::invokeMethod(udpCommWorker,
                                  "sendStatusNow",
                                  Qt::QueuedConnection);
    }

    displayInfo(QStringLiteral("UDP后置回中：启动从当前位姿到UDP中位的内部直线轨迹，仿真通过后下发，时长%1s，步长%2ms")
                .arg(durationSec, 0, 'f', 3)
                .arg(kUdpReturnHomeDefaultStepSec * 1000.0, 0, 'f', 3)
                .toStdString(),
                "info");

    const bool started = startActiveRunMode(false);
    if(!started){
        udpReturnHomeInProgress = false;
        updateUdpStatusPayload();
        displayInfo("错误：UDP后置回中内部直线轨迹启动失败", "error");
        return false;
    }
    return true;
}

quint32 MainWindow::udpPlatformFeedbackStateForRobotState(const RobotStateSnapshot& robotState) const
{
    const bool udpTrajectoryOccupied =
            udpProgramControlExternalTrajectoryStarting ||
            udpProgramControlExternalTrajectoryActive ||
            udpReturnHomePending ||
            udpReturnHomeInProgress ||
            udpPlatformTrajectoryCaptureArmed ||
            !udpPlatformTrajectoryPointBuffer.isEmpty();
    const bool v9NoHardwareSimulationTest =
            udpV9NoHardwareSimulationTestModeEnabled();
    if(!robotState.systemRunning && !v9NoHardwareSimulationTest){
        return 0u;
    }
    if(robotState.anyMotionRunning || udpTrajectoryOccupied){
        return 2u;
    }
    if(v9NoHardwareSimulationTest){
        return 3u;
    }
    return udpPlatformAtReceiveHomePose() ? 3u : 1u;
}

QString MainWindow::udpPlatformStateDisplayText(quint32 state) const
{
    switch(state){
    case 0:
        return QStringLiteral("未使能");
    case 1:
        return QStringLiteral("使能空闲/不在UDP中位");
    case 2:
        return QStringLiteral("使能运动/轨迹占用");
    case 3:
        return QStringLiteral("在UDP中位/可接收");
    default:
        return QStringLiteral("未知");
    }
}

bool MainWindow::udpPlatformCanReceiveTrajectoryPoints() const
{
    const RobotStateSnapshot robotState = currentRobotState(false);
    return udpPlatformFeedbackStateForRobotState(robotState) == 3u;
}

