            singleMotorPointMoveActive ||
            runtimeState.jogFollowTestActive ||
            runtimeState.onlineVelocityControlActive;
    const bool pvtMotionProtectedActive =
            runtimeState.pvtMotionProtectedActive ||
            runtimeState.pvtCommandActive;
    config.axisCount = ui->devAxisNum->value();
    config.sensorCount = axisForceSensorNum;
    config.ctrlCycleMs = ui->devCtrlCycleMs->value();
    config.sensorSampleHz = configuredSensorSampleFrequencyHz();
    config.forceSensorTraceSamplePeriodUs =
            forceSensorTraceSamplePeriodUsFromHz(static_cast<int>(config.sensorSampleHz));
    config.forceSensorLowPassCutoffHz = configuredForceSensorLowPassCutoffHz();
    config.systemRunning = runtimeState.systemRunning;
    config.commissioningModeActive =
            runtimeState.hardwareRunState == HardwareRunState::SingleAxisCommissioning &&
            runtimeState.commissioningAxisIndex >= 0;
    config.commissioningAxisIndex = config.commissioningModeActive ?
                runtimeState.commissioningAxisIndex : -1;
    config.useLeadshine = ui->devUseLS->isChecked();
