            findOptionalUiObject<QPushButton>(this, "forcePidTuningClearPlotButton");
    forcePidTuningExclusiveRefreshButton =
            findOptionalUiObject<QPushButton>(this, "forcePidTuningExclusiveRefreshButton");
    forcePidTuningRecordButton =
            findOptionalUiObject<QPushButton>(this, "forcePidTuningRecordButton");
    forcePidTuningResponsePlotHost =
            findOptionalUiObject<QCustomPlot>(this, "forcePidTuningResponsePlotHost");
    forcePidTuningUseFCBtnVec = {
        findOptionalUiObject<QRadioButton>(this, "forcePidTuningUseFC"),
        findOptionalUiObject<QRadioButton>(this, "forcePidTuningUseFC_2"),
        findOptionalUiObject<QRadioButton>(this, "forcePidTuningUseFC_3"),
        findOptionalUiObject<QRadioButton>(this, "forcePidTuningUseFC_4"),
        findOptionalUiObject<QRadioButton>(this, "forcePidTuningUseFC_5"),
        findOptionalUiObject<QRadioButton>(this, "forcePidTuningUseFC_6"),
        findOptionalUiObject<QRadioButton>(this, "forcePidTuningUseFC_7"),
        findOptionalUiObject<QRadioButton>(this, "forcePidTuningUseFC_8")
    };

    const auto syncDoubleSpin = [this](QDoubleSpinBox* source, QDoubleSpinBox* mirror){
        if(!source || !mirror){
            return;
        }
        mirror->setRange(source->minimum(), source->maximum());
        mirror->setDecimals(source->decimals());
        mirror->setSingleStep(source->singleStep());
        mirror->setSuffix(source->suffix());
        mirror->setToolTip(source->toolTip());
        mirror->setKeyboardTracking(source->keyboardTracking());
        mirror->setEnabled(source->isEnabled());
        mirror->setValue(source->value());
        connect(source,
                QOverload<double>::of(&QDoubleSpinBox::valueChanged),
                this,
                [mirror](double value){
            mirror->setValue(value);
        });
        connect(mirror,
                QOverload<double>::of(&QDoubleSpinBox::valueChanged),
                this,
                [source](double value){
            source->setValue(value);
        });
    };
    const auto syncCheckBox = [this](QCheckBox* source, QCheckBox* mirror){
        if(!source || !mirror){
            return;
        }
        mirror->setToolTip(source->toolTip());
        mirror->setEnabled(source->isEnabled());
        mirror->setChecked(source->isChecked());
        connect(source, &QCheckBox::toggled, this, [mirror](bool checked){
            mirror->setChecked(checked);
        });
        connect(mirror, &QCheckBox::toggled, this, [source](bool checked){
            source->setChecked(checked);
        });
    };

    syncDoubleSpin(ui->devFCKp, findOptionalUiObject<QDoubleSpinBox>(this, "forcePidTuningKp"));
    syncDoubleSpin(ui->devFCKi, findOptionalUiObject<QDoubleSpinBox>(this, "forcePidTuningKi"));
    syncDoubleSpin(ui->devFCKd, findOptionalUiObject<QDoubleSpinBox>(this, "forcePidTuningKd"));
    syncDoubleSpin(ui->devFCInitForce,
                   findOptionalUiObject<QDoubleSpinBox>(this, "forcePidTuningInitForce"));
    syncDoubleSpin(ui->devFCDeadbandPercent,
                   findOptionalUiObject<QDoubleSpinBox>(this, "forcePidTuningDeadbandPercent"));
    syncDoubleSpin(findOptionalUiObject<QDoubleSpinBox>(this, "devFCFeedForwardScale"),
                   findOptionalUiObject<QDoubleSpinBox>(this, "forcePidTuningFeedForwardScale"));
