    forcePidTuningContinuousAmplitudeSpin->setSuffix(QStringLiteral(" N"));
    forcePidTuningContinuousAmplitudeSpin->setMinimumWidth(80);

    forcePidTuningContinuousFrequencySpin = new QDoubleSpinBox(group);
