    const auto configureOptionalForceSpin =
            [this](const char* objectName,
                   double minValue,
                   double maxValue,
                   int decimals,
                   double step,
                   double value,
                   const QString& suffix = QString(),
                   const QString& toolTip = QString()){
        if(QDoubleSpinBox* spin = findOptionalUiObject<QDoubleSpinBox>(this, objectName)){
            spin->setRange(minValue, maxValue);
            spin->setDecimals(decimals);
            spin->setSingleStep(step);
            spin->setSuffix(suffix);
            if(!toolTip.isEmpty()){
                spin->setToolTip(toolTip);
            }
            spin->setValue(value);
            connect(spin,
                    QOverload<double>::of(&QDoubleSpinBox::valueChanged),
                    this,
                    [this](double){
                requestImmediateForceControlUpdate();
            });
        }
    };
