    connect(ui->mainFCThread,&QCheckBox::toggled,this,[this](bool checked){
        if(suppressForceControlSelectionSideEffects){
            return;
        }
        if(checked){
            const bool liteCommissioning =
                    isLiteTemplateActive() &&
                    !runtimeState.systemRunning &&
                    runtimeState.hardwareRunState != HardwareRunState::Disconnected;
            if(liteCommissioning){
                const int axisIndex = selectedLiteCommissioningAxis();
                bool selectionMatches = false;
                int sensorIndex = -1;
                if(axisIndex >= 0 &&
                        axisIndex < static_cast<int>(axisSensorIndexVec.size()) &&
                        axisSensorIndexVec[axisIndex]){
                    sensorIndex = axisSensorIndexVec[axisIndex]->value();
                    int checkedCount = 0;
                    for(int index = 0; index < static_cast<int>(useFCBtnVec.size()); ++index){
                        if(useFCBtnVec[index] && useFCBtnVec[index]->isChecked()){
                            ++checkedCount;
                            selectionMatches = index == sensorIndex;
                        }
                    }
                    selectionMatches = selectionMatches && checkedCount == 1;
                }
                double effectiveForceLimit = liteCommissioningMaxForceSpin->value();
                if(axisIndex >= 0 &&
                        axisIndex < static_cast<int>(axisForceMaxVec.size()) &&
                        axisForceMaxVec[axisIndex] &&
                        std::isfinite(axisForceMaxVec[axisIndex]->value()) &&
                        axisForceMaxVec[axisIndex]->value() > 0.0){
                    effectiveForceLimit = std::min(effectiveForceLimit,
                                                   axisForceMaxVec[axisIndex]->value());
                }
                const bool expectedForceWithinLimit =
                        sensorIndex >= 0 &&
                        sensorIndex < static_cast<int>(mainForceSensorExp.size()) &&
                        mainForceSensorExp[sensorIndex] &&
                        std::isfinite(mainForceSensorExp[sensorIndex]->value()) &&
                        mainForceSensorExp[sensorIndex]->value() >= 0.0 &&
                        mainForceSensorExp[sensorIndex]->value() <=
                            effectiveForceLimit;
                HardwareInterface::ConnectionItemDiagnostics sensorDiagnostics;
                HardwareInterface::ConnectionItemDiagnostics axisDiagnostics;
                runLiteCommissioningHardwareCommand([&](){
                    if(sensorIndex >= 0){
                        sensorDiagnostics =
                                hardwareInterface.forceSensorDiagnostics(sensorIndex);
                    }
                    if(axisIndex >= 0){
                        axisDiagnostics =
                                hardwareInterface.motorAxisDiagnostics(axisIndex);
                    }
                }, QStringLiteral("启动单绳力控前诊断"));
                const bool sensorFresh =
                        sensorIndex >= 0 &&
                        sensorDiagnostics.state ==
                            HardwareInterface::ConnectionState::Connected;
                const bool axisDirectReady =
                        axisDiagnostics.state == HardwareInterface::ConnectionState::Connected &&
                        axisDiagnostics.stateMachine == 4 &&
                        axisDiagnostics.errorCode == 0;
                if(axisIndex != runtimeState.commissioningAxisIndex ||
                        !ensureLiteControllerReady(QStringLiteral("单绳力控启动")) ||
                        !ensureLiteAxisReady(axisIndex,
                                             QStringLiteral("单绳力控启动"),
                                             true,
                                             true,
                                             true) ||
                        !axisDirectReady ||
                        !isSingleCableForceDebugModeActive() ||
                        !selectionMatches ||
                        !expectedForceWithinLimit ||
                        !sensorFresh ||
                        runtimeState.motorTorqueDebugActive ||
                        runtimeState.singleMotorPointMoveActive ||
                        runtimeState.jogFollowTestActive ||
                        jogFollowTestRunning){
                    const QSignalBlocker blocker(ui->mainFCThread);
                    ui->mainFCThread->setChecked(false);
                    displayInfo(QStringLiteral("错误：Lite 单绳力控启动被拒绝。请使用调试页准备0525 PID，确保只选目标轴传感器且期望力不超过有效上限%1 N")
                                .arg(effectiveForceLimit, 0, 'f', 1)
                                .toStdString(),
                                "error");
                    requestImmediateForceControlUpdate();
                    return;
                }
            }
            if(!ensureForceControlExpectedForceReady(QStringLiteral("力控线程启动"))){
                const QSignalBlocker blocker(ui->mainFCThread);
                ui->mainFCThread->setChecked(false);
                cancelManualForceControlPretensionRamp(true);
                requestImmediateForceControlUpdate();
                return;
            }
            if(liteCommissioning){
                runtimeState.commissioningAxisIndex = selectedLiteCommissioningAxis();
                runtimeState.commissioningMotionStartMs = QDateTime::currentMSecsSinceEpoch();
                runtimeState.safetyArmed = true;
                updateControlWorkerConfig();
                updateSafetyMonitorConfig();
            }
            if(runtimeState.cableHomeState != CableHomeState::Confirmed){
                runtimeState.cableHomeState = CableHomeState::WaitingForceStable;
                updateCableHomeConfirmEnabled();
            }
            startForcePidTuningContinuousForceSequenceClockIfReady();
            startManualForceControlPretensionRampForCurrentSelection();
        }
        else{
            cancelManualForceControlPretensionRamp(true);
            if(runtimeState.hardwareRunState == HardwareRunState::SingleAxisCommissioning &&
                    !runtimeState.motorTorqueDebugActive &&
                    !runtimeState.singleMotorPointMoveActive &&
                    !runtimeState.jogFollowTestActive){
                runtimeState.commissioningMotionStartMs = -1;
                updateControlWorkerConfig();
                updateSafetyMonitorConfig();
            }
        }
        requestImmediateForceControlUpdate();
    });
    connect(ui->mainDevInfoOutputTrigger,&IntBtn::sendInt,this,&MainWindow::outputInfoSendTrigger);
