    connect(controlSnapshotTimer, &QTimer::timeout, this, [this](){
        // GUI_PERF_DIAG：最后一个连接闭合本轮总段，保持原有回调顺序不变。
        guiTimingDiagnostics.endControlSnapshotDispatch();
    });
    controlSnapshotTimer->start();

    forcePidTraceDrainTimer = new QTimer(this);
    forcePidTraceDrainTimer->setTimerType(Qt::CoarseTimer);
    forcePidTraceDrainTimer->setInterval(kForcePidTraceDrainIntervalMs);
