    safetyHeartbeatTimer->start();

    resetRuntimeDiagnosticsState(true);

    startSafetyMonitor();

    positionThread = new QThread(this);
    pvtExecutionWorker = new PvtExecutionWorker(&hardwareInterface);
    pvtExecutionWorker->moveToThread(positionThread);
