    ui->mainPosModeTargetRunTime->setValue(8);
    ui->mainPosModeTargetStepTime->setValue(100.0);
    ui->devUseLite->setChecked(true);
    paraChange();
    refreshAxisRuntimeCounts();

    if(!init3DViewer())
        return false;
    updatePara();
    startMonitor();
    
    // 轨迹完成检测定时器
    trajectoryCheckTimer = new QTimer(this);
    trajectoryCheckTimer->setTimerType(Qt::PreciseTimer);
    connect(trajectoryCheckTimer, &QTimer::timeout, this, &MainWindow::checkTrajectoryFinished);
    
    captureDefaultParameterConfigSnapshot();

    return true;
