        ui->mainResetMotiveFit->setEnabled(true);
        const std::vector<double> initialUiPose =
                platformPoseToPositionModeUiPose({kGlobalInitialPosePxMm,
                                                  kGlobalInitialPosePyMm,
                                                  kGlobalInitialPosePzMm,
                                                  kGlobalInitialPoseRxRad,
                                                  kGlobalInitialPoseRyRad,
                                                  kGlobalInitialPoseRzRad},
                                                 positionModeUiRxOffsetRad());
        ui->mainPosModeTargetStartPx->setValue(initialUiPose[0]);
