void MainWindow::applyLiteTemplateParameters(){
    // Lite 先复用 G3 原始模板，再在本函数中覆盖缩小版物理场景的差异参数。
    applyG3TemplateParameters();
    endMassVec[0]->setValue(kLiteDefaultEndMassKg);
    const MachineKinematicsProfile& profile =
            machineKinematicsProfile(MachineProfileKind::Lite);
    QString ignoredForcePidWarning;
    applyForcePidParameterSnapshot(liteForcePidDefaultWidgetValues(),
                                   &ignoredForcePidWarning);
    hardwareInterface.setRuntimeTraceConfigType(profile.runtimeTraceConfigType);
    hardwareInterface.setLeadshineRatedMotorTorqueNm(profile.leadshineRatedMotorTorqueNm);
    ui->devFSDataLen->setValue(profile.forceSensorDataLen);// Lite 12通道变送器PDO为DINT
    ui->axisIsForceSensorSigned->setChecked(profile.forceSensorSigned);
    ui->axisIsStaticSensorHome->setChecked(profile.staticSensorHome);
    ui->devFrameL->setValue(profile.frameLengthMm);// Lite x轴平行边，单位 mm
    ui->devFrameW->setValue(profile.frameWidthMm);// Lite y轴平行边，单位 mm
    ui->devFrameH->setValue(profile.frameHeightMm);// Lite z轴高度，单位 mm
    ui->devPulleyRadius->setValue(profile.pulleyRadiusMm);
    optionalSpinBoxSetValue(this, "devBarycenterForceMinN", profile.barycenterForceMinN);
    optionalSpinBoxSetValue(this, "devBarycenterForceMaxN", profile.barycenterForceMaxN);
    optionalSpinBoxSetValue(this,
                            kWorkspaceWarningMarginParameterName,
                            profile.workspaceWarningMarginMm);
    const int modeledCableAxisCount = profile.modeledCableAxisCount;
    ui->motorTorqueLimitNm->setValue(profile.actualTorqueLimitNm);
    enforceMachineTorqueLimitsOnUi();
    if(motorTorqueServoVelocityLimitSpin){
        motorTorqueServoVelocityLimitSpin->setValue(profile.torqueServoVelocityLimitRpm);
    }
    for(int i = 0;
        i < modeledCableAxisCount && i < static_cast<int>(axisMotorCofVec.size());
        ++i){
        if(i < static_cast<int>(profile.hardwareAxisNo.size()) &&
                i < static_cast<int>(axisMotorHardwareAxisVec.size()) &&
                axisMotorHardwareAxisVec[i]){
            axisMotorHardwareAxisVec[i]->setValue(profile.hardwareAxisNo[i]);
        }
        if(i < static_cast<int>(profile.slaveId.size()) &&
                i < static_cast<int>(axisMotorSlaveIdVec.size()) &&
                axisMotorSlaveIdVec[i]){
            axisMotorSlaveIdVec[i]->setValue(profile.slaveId[i]);
        }
        if(axisMotorCofVec[i]){
            axisMotorCofVec[i]->setValue(profile.cableWinchRadiusMm);
        }
        if(i < static_cast<int>(axisMotorMaxVec.size()) && axisMotorMaxVec[i]){
            axisMotorMaxVec[i]->setValue(profile.cableMotorPosLimitRev);
        }
        if(i < static_cast<int>(axisMotorMinVec.size()) && axisMotorMinVec[i]){
            axisMotorMinVec[i]->setValue(-profile.cableMotorPosLimitRev);
        }
        if(i < static_cast<int>(axisMotorVelMaxVec.size()) && axisMotorVelMaxVec[i]){
            axisMotorVelMaxVec[i]->setValue(profile.cableMotorVelLimitRevPerSec);
        }
        if(i < static_cast<int>(axisForceMaxVec.size()) && axisForceMaxVec[i]){
            axisForceMaxVec[i]->setValue(profile.cableForceLimitN);
        }
        if(i < static_cast<int>(axisSensorCofVec.size()) &&
                i < static_cast<int>(profile.forceSensorCof.size()) &&
                axisSensorCofVec[i]){
            axisSensorCofVec[i]->setValue(profile.forceSensorCof[i]);
        }
    }
    if(!profile.linearModuleHeightModuleEnabled){
        ui->devAxisNum->setValue(modeledCableAxisCount);
        for(int i = modeledCableAxisCount;
            i < static_cast<int>(axisTypeVec.size());
            ++i){
            if(axisTypeVec[i]){
                axisTypeVec[i]->setCurrentIndex(0);
            }
            if(axisEndVec[i]){
                axisEndVec[i]->setValue(-1);
            }
            if(axisSensorIndexVec[i]){
                axisSensorIndexVec[i]->setValue(-1);
            }
            if(axisMotorHardwareAxisVec[i]){
                axisMotorHardwareAxisVec[i]->setValue(i);
            }
            if(axisMotorSlaveIdVec[i]){
                axisMotorSlaveIdVec[i]->setValue(0);
            }
            if(axisSensorCofVec[i]){
                axisSensorCofVec[i]->setValue(0.0);
            }
            if(axisMotorCofVec[i]){
                axisMotorCofVec[i]->setValue(0.0);
            }
        }
        refreshAxisRuntimeCounts();
        refreshLinearModuleHeightUi(false);
    }
}

void MainWindow::updatePara(){
    QStringList appliedItems;
    QStringList skippedItems;
    QStringList noteItems;
    bool updateHasError = false;
    auto appendUnique = [](QStringList& items, const QString& item){
        if(!item.isEmpty() && !items.contains(item)){
            items.append(item);
        }
    };
    auto appendReportSection = [](QStringList& lines,
                                  const QString& title,
                                  const QStringList& items){
        if(items.isEmpty()){
            return;
        }
        lines.append(title);
        for(const QString& item : items){
            lines.append(QStringLiteral("  - %1").arg(item));
        }
    };
    auto buildReport = [&](const QString& title) -> QString {
        QStringList lines;
        lines.append(title);
        appendReportSection(lines, QStringLiteral("已更新/应用："), appliedItems);
        appendReportSection(lines, QStringLiteral("已跳过："), skippedItems);
        appendReportSection(lines, QStringLiteral("说明："), noteItems);
        return lines.join(QLatin1Char('\n'));
    };

    if(runtimeState.systemRunning){
        refreshAxisRuntimeCounts();
        appendUnique(appliedItems,
                     QStringLiteral("刷新轴和张力传感器数量缓存：轴数=%1，张力传感器数=%2")
                     .arg(ui->devAxisNum->value())
                     .arg(axisForceSensorNum));
        resetFCPIDPara();
        appendUnique(appliedItems, QStringLiteral("刷新力控PID参数缓存"));
        hardwareInterface.threadCtrlCycleMs = (double)ui->devCtrlCycleMs->value();
        appendUnique(appliedItems,
                     QStringLiteral("同步硬件接口控制周期：%1 ms")
                     .arg(QString::number(ui->devCtrlCycleMs->value(), 'f', 3)));
        if(motiveLocalHandlerThread){
            motiveLocalHandlerThread->ctrlCycleMs = (double)(ui->devCtrlCycleMs->value());
            appendUnique(appliedItems,
                         QStringLiteral("同步动捕线程控制周期：%1 ms")
                         .arg(QString::number(ui->devCtrlCycleMs->value(), 'f', 3)));
        }
        else{
            appendUnique(skippedItems, QStringLiteral("动捕线程控制周期同步（当前未创建动捕线程）"));
        }
        if(linearModuleHeightModuleEnabled()){
            syncUpperAnchorStartPosWithLinearModuleHeight(false);
            appendUnique(appliedItems, QStringLiteral("同步上锚点初始高度和工作空间高度参数"));
        }
        else{
            appendUnique(skippedItems,
                         QStringLiteral("上锚点Z和工作空间高度随直线模组高度同步（Lite模板未启用）"));
        }
        updateControlWorkerConfig();
        const int sensorSampleHz = configuredSensorSampleFrequencyHz();
        appendUnique(appliedItems,
                     QStringLiteral("刷新控制线程运行配置：主控周期=%1 ms，张力采样目标=%2 Hz，Trace周期=%3 us")
                     .arg(QString::number(ui->devCtrlCycleMs->value(), 'f', 3))
                     .arg(sensorSampleHz)
                     .arg(forceSensorTraceSamplePeriodUsFromHz(sensorSampleHz)));
        updateSafetyMonitorConfig();
        appendUnique(appliedItems, QStringLiteral("刷新安全监控配置"));
        refreshSafetyMonitorHeartbeat();
        appendUnique(appliedItems, QStringLiteral("刷新安全监控心跳"));
        appendUnique(skippedItems, QStringLiteral("完整参数重建（系统运行中）"));
        appendUnique(skippedItems, QStringLiteral("雷赛硬件参数整组下发（系统运行中）"));
        appendUnique(skippedItems, QStringLiteral("电机软件限位下发（系统运行中）"));
        appendUnique(skippedItems, QStringLiteral("动捕线程重建（系统运行中）"));
        appendUnique(skippedItems, QStringLiteral("一般控制线程和监控线程重启（系统运行中）"));
        appendUnique(noteItems, QStringLiteral("轴号、脉冲当量、动捕类型、模块数量等结构性配置需要断连或停机后再更新"));
        displayInfo(buildReport(QStringLiteral("更新并应用参数完成：系统运行中，仅同步允许运行时更新的参数。")).toStdString(),
                    "warning");
        return;
    }

    refreshAxisRuntimeCounts();
    appendUnique(appliedItems,
                 QStringLiteral("刷新轴和张力传感器数量缓存：轴数=%1，张力传感器数=%2")
                 .arg(ui->devAxisNum->value())
                 .arg(axisForceSensorNum));
    forceSensorCurHome = std::vector<double>(axisForceSensorNum,0.0);
    appendUnique(appliedItems, QStringLiteral("重置张力传感器当前零点缓存"));
    resetFCPIDPara();
    appendUnique(appliedItems, QStringLiteral("刷新力控PID参数缓存"));

    // 动捕
    const QString camTypeText = ui->devCamTypeBox->currentText().trimmed();
    if(camTypeText == QStringLiteral("/"))
        useCam = false;
    else
        useCam = true;

    const bool hadMotiveThread = motiveLocalHandlerThread || mlhThread;
    stopMotiveThread();
    if(hadMotiveThread){
        appendUnique(appliedItems, QStringLiteral("停止旧动捕线程并清理旧连接"));
    }
    else{
        appendUnique(skippedItems, QStringLiteral("旧动捕线程停止（当前无旧动捕线程）"));
    }

    if(useCam){
        ui->devUpdateParaBtn->setEnabled(false);
        delay(100);
        motiveLocalHandlerThread = new MotiveLocalHandlerThread(ui->devCtrlCycleMs->value());
        if(motiveLocalHandlerThread->isInit){
            mlhThread = new QThread(this);
            motiveLocalHandlerThread->moveToThread(mlhThread);
            connect(mlhThread, &QThread::started, motiveLocalHandlerThread, &MotiveLocalHandlerThread::startTimer);
            connect(mlhThread, &QThread::finished, motiveLocalHandlerThread, &MotiveLocalHandlerThread::stopTimer);

            disconnect(ui->mainResetMotiveFit,
                       &IntBtn::sendInt,
                       this,
                       &MainWindow::resetMotiveFit);
            connect(ui->mainResetMotiveFit,
                    &IntBtn::sendInt,
                    this,
                    &MainWindow::resetMotiveFit);
            disconnect(motiveLocalHandlerThread,
                       &MotiveLocalHandlerThread::dataUpdateSignal,
                       this,
                       &MainWindow::handleVisualizationRigidPose);
            connect(motiveLocalHandlerThread,
                    &MotiveLocalHandlerThread::dataUpdateSignal,
                    this,
                    &MainWindow::handleVisualizationRigidPose);
            connect(motiveLocalHandlerThread,
                    &MotiveLocalHandlerThread::poseCaptureCompleted,
                    this,
                    &MainWindow::handleMotivePoseCaptureCompleted);
            connect(motiveLocalHandlerThread,
                    &MotiveLocalHandlerThread::poseCaptureFailed,
                    this,
                    &MainWindow::handleMotivePoseCaptureFailed);
            appendUnique(appliedItems,
                         QStringLiteral("重建动捕线程：类型=%1，控制周期=%2 ms")
                         .arg(camTypeText)
                         .arg(QString::number(ui->devCtrlCycleMs->value(), 'f', 3)));
        }
        else{
            displayInfo("Failed to connect to the camera server, please restart the system and check connection.","error");
            updateHasError = true;
            appendUnique(skippedItems, QStringLiteral("动捕线程启动（连接相机服务器失败）"));
            delete motiveLocalHandlerThread;
            motiveLocalHandlerThread = nullptr;
        }
        ui->devUpdateParaBtn->setEnabled(true);
    }
    else{
        appendUnique(skippedItems, QStringLiteral("动捕线程重建（动捕类型为/，未启用动捕）"));
    }

    // 硬件参数
    if(ui->devUseLS->isChecked()){
        if(!applyLeadshineHardwareConfigFromUi(&appliedItems, &skippedItems)){
            appendUnique(skippedItems, QStringLiteral("后续参数应用（雷赛硬件参数应用失败后停止）"));
            displayInfo(buildReport(QStringLiteral("更新并应用参数失败：雷赛硬件参数未完整应用。")).toStdString(),
                        "error");
            return;
        }
    }
    else{
        appendUnique(skippedItems, QStringLiteral("雷赛硬件参数下发（未启用雷赛控制）"));
        syncMotorSoftwareLimitsToHardware(&appliedItems, &skippedItems);
    }

    fcOneDimKalmanHandler = OneDimKalmanHandler(axisForceSensorNum);
    fcOneDimKalmanHandler.setCov(std::vector<double>(axisForceSensorNum,0.0),std::vector<double>(axisForceSensorNum,0.002),
                                 std::vector<double>(axisForceSensorNum,0.05));// 0.002 50.0; 0.002 0.05
    appendUnique(appliedItems,
                 QStringLiteral("重建张力一维Kalman滤波器：通道数=%1")
                 .arg(axisForceSensorNum));

    hardwareInterface.threadCtrlCycleMs = (double)ui->devCtrlCycleMs->value();
    appendUnique(appliedItems,
                 QStringLiteral("同步硬件接口控制周期：%1 ms")
                 .arg(QString::number(ui->devCtrlCycleMs->value(), 'f', 3)));
    if(motiveLocalHandlerThread){
        motiveLocalHandlerThread->ctrlCycleMs = (double)(ui->devCtrlCycleMs->value());
        appendUnique(appliedItems,
                     QStringLiteral("同步动捕线程控制周期：%1 ms")
                     .arg(QString::number(ui->devCtrlCycleMs->value(), 'f', 3)));
    }
    else{
        appendUnique(skippedItems, QStringLiteral("动捕线程控制周期同步（当前未创建动捕线程）"));
    }
    if(linearModuleHeightModuleEnabled()){
        syncUpperAnchorStartPosWithLinearModuleHeight(false);
        appendUnique(appliedItems, QStringLiteral("同步上锚点初始高度和工作空间高度参数"));
    }
    else{
        appendUnique(skippedItems,
                     QStringLiteral("上锚点Z和工作空间高度随直线模组高度同步（Lite模板未启用）"));
    }
    updateControlWorkerConfig();
    const int sensorSampleHz = configuredSensorSampleFrequencyHz();
    appendUnique(appliedItems,
                 QStringLiteral("刷新控制线程配置：主控周期=%1 ms，张力采样目标=%2 Hz，Trace周期=%3 us")
                 .arg(QString::number(ui->devCtrlCycleMs->value(), 'f', 3))
                 .arg(sensorSampleHz)
                 .arg(forceSensorTraceSamplePeriodUsFromHz(sensorSampleHz)));
    appendUnique(skippedItems, QStringLiteral("控制线程配置刷新中的电机软件限位重复同步（已在前一阶段处理或判定未变化）"));

    ensurePoseKinematicsHelpersReady(true);
    appendUnique(appliedItems, QStringLiteral("确认位姿运动学辅助对象可用"));

    // 启动线程
    if(ccThread && !ccThread->isRunning()){
        ccThread->start(QThread::HighPriority);
        appendUnique(appliedItems, QStringLiteral("启动一般控制线程"));
    }
    else if(ccThread){
        appendUnique(skippedItems, QStringLiteral("一般控制线程启动（线程已在运行）"));
    }
    else{
        appendUnique(skippedItems, QStringLiteral("一般控制线程启动（线程对象不存在）"));
    }
    if(motiveLocalHandlerThread && motiveLocalHandlerThread->isInit && mlhThread && !mlhThread->isRunning()){
        mlhThread->start();
        appendUnique(appliedItems, QStringLiteral("启动动捕线程"));
    }
    else if(motiveLocalHandlerThread && motiveLocalHandlerThread->isInit && mlhThread){
        appendUnique(skippedItems, QStringLiteral("动捕线程启动（线程已在运行）"));
    }
    else if(useCam){
        appendUnique(skippedItems, QStringLiteral("动捕线程启动（线程未初始化）"));
    }
    else{
        appendUnique(skippedItems, QStringLiteral("动捕线程启动（未启用动捕）"));
    }
    stopMonitor();
    startMonitor();
    appendUnique(appliedItems, QStringLiteral("重启监控线程"));
    refreshLinearModuleHeightUi(false);
    appendUnique(appliedItems, QStringLiteral("刷新直线模组高度显示"));
    updateSafetyMonitorConfig();
    appendUnique(appliedItems, QStringLiteral("刷新安全监控配置"));
    displayInfo(buildReport(updateHasError ?
                                QStringLiteral("更新并应用参数完成：部分内容失败，其他参数已继续应用。") :
                                QStringLiteral("更新并应用参数完成：已按当前界面参数执行完整更新。")).toStdString(),
                updateHasError ? "error" : "normal");
}

bool MainWindow::applyLeadshineHardwareConfigFromUi(QStringList* appliedItems,
                                                    QStringList* skippedItems,
                                                    bool writeConnectedAxisEquiv)
{
    auto appendItem = [](QStringList* items, const QString& item){
        if(items && !item.isEmpty() && !items->contains(item)){
            items->append(item);
        }
    };

    if(!ui->devUseLS->isChecked()){
        appendItem(skippedItems, QStringLiteral("雷赛硬件参数下发（未启用雷赛控制）"));
        return true;
    }
    if(writeConnectedAxisEquiv &&
            hardwareInterface.isLSConnected() &&
            runtimeState.hardwareRunState == HardwareRunState::SingleAxisCommissioning){
        appendItem(skippedItems,
                   QStringLiteral("Lite 单轴调试中拒绝全轴参数写入"));
        displayInfo("错误：Lite 单轴调试连接中禁止下发全轴参数，请使用调试页的“下发当前轴参数”", "error");
        return false;
    }

    std::vector<int> sensorAdr(axisForceSensorNum);
    std::vector<int> sensorDataAdr(axisForceSensorNum);
    std::vector<double> sensorCof(axisForceSensorNum);

    for(int i=0;i<ui->devAxisNum->value();++i){
        if(axisSensorIndexVec[i]->value()>=0){
            const int sensorIndex = axisSensorIndexVec[i]->value();
            sensorAdr[sensorIndex] = sensorIndex * 2;
            sensorDataAdr[sensorIndex] = sensorIndex;
            sensorCof[sensorIndex] = axisSensorCofVec[i]->value();
        }
    }
    hardwareInterface.setSensorPara(std::vector<int>(axisForceSensorNum,COM_EC_LS_SBT),
                                    std::vector<int>(axisForceSensorNum,ui->devFSPortNum->value()),
                                    sensorAdr,sensorDataAdr,std::vector<int>(axisForceSensorNum,ui->devFSDataLen->value()),
                                    sensorCof);
    appendItem(appliedItems,
               QStringLiteral("下发张力传感器硬件参数：通道数=%1，端口=%2，数据长度=%3")
               .arg(axisForceSensorNum)
               .arg(ui->devFSPortNum->value())
               .arg(ui->devFSDataLen->value()));
    hardwareInterface.setForceSensorIsSigned(ui->axisIsForceSensorSigned->isChecked());
    appendItem(appliedItems,
               QStringLiteral("下发张力传感器符号位：%1")
               .arg(ui->axisIsForceSensorSigned->isChecked() ?
                        QStringLiteral("有符号") :
                        QStringLiteral("无符号")));

    std::vector<unsigned int> motorIDVec(ui->devAxisNum->value(), 0U);
    std::vector<int> comType(ui->devAxisNum->value(), 0);
    std::vector<int> motorSlaveIdVec(ui->devAxisNum->value(), 0);
    std::vector<bool> motorTorqueVelocityLimitEnabled(ui->devAxisNum->value(), false);
    QSet<int> usedHardwareAxis;
    bool hasLeadshineAxis = false;
    for(int i=0;i<static_cast<int>(motorIDVec.size());++i){
        const bool motorAxis = isMotorAxis(i);
        const int configuredHardwareAxisNo = axisMotorHardwareAxisVec[i]->value();
        const int configuredSlaveId = axisMotorSlaveIdVec[i]->value();
        if(i == 0 || configuredHardwareAxisNo == 0){
            const QVariant axisTypeData = axisTypeVec[i]->currentData(Qt::UserRole);
            displayInfo(QStringLiteral("雷赛配置调试：%1，类型=\"%2\"，类型数据=%3，isMotor=%4，控制卡轴号=%5")
                        .arg(motorAxisDisplayName(i))
                        .arg(axisTypeVec[i]->currentText().trimmed())
                        .arg(axisTypeData.isValid() ? QString::number(axisTypeData.toInt()) : QStringLiteral("invalid"))
                        .arg(motorAxis ? QStringLiteral("true") : QStringLiteral("false"))
                        .arg(configuredHardwareAxisNo)
                        .toStdString(),
                        motorAxis ? "info" : "warning");
        }
        if(!motorAxis){
            continue;
        }

        hasLeadshineAxis = true;
        if(configuredHardwareAxisNo < kLeadshineHardwareAxisMin ||
                configuredHardwareAxisNo > kLeadshineHardwareAxisMax){
            displayInfo(QStringLiteral("错误：%1的控制卡轴号必须设置为0到11").arg(motorAxisDisplayName(i)).toStdString(), "error");
            return false;
        }

        const int hardwareAxisIndex = configuredHardwareAxisNo;
        if(usedHardwareAxis.contains(hardwareAxisIndex)){
            displayInfo(QStringLiteral("错误：逻辑电机轴配置了重复的控制卡轴号 %1").arg(configuredHardwareAxisNo).toStdString(), "error");
            return false;
        }

        usedHardwareAxis.insert(hardwareAxisIndex);
        motorIDVec[i] = static_cast<unsigned int>(hardwareAxisIndex);
        motorSlaveIdVec[i] = configuredSlaveId;
        motorTorqueVelocityLimitEnabled[i] = !isLinearMotorAxis(i);
        comType[i] = COM_EC_LS;
    }

    if(!hasLeadshineAxis){
        displayInfo("错误：当前未配置任何雷赛电机", "error");
        return false;
    }

    const MachineKinematicsProfile& profile =
            currentMachineKinematicsProfile(ui);
    const double ratedMotorTorqueNm = profile.leadshineRatedMotorTorqueNm;
    hardwareInterface.setRuntimeTraceConfigType(profile.runtimeTraceConfigType);
    if(profile.runtimeTraceConfigType == HardwareInterface::RuntimeTraceConfigType::Lite){
        hardwareInterface.setLiteRuntimeTraceTopology(selectedLiteRuntimeTraceTopology());
        appendItem(appliedItems,
                   selectedLiteRuntimeTraceTopology() ==
                       HardwareInterface::LiteRuntimeTraceTopology::TemporarySevenAxisSensorSlave1008 ?
                       QStringLiteral("下发Lite Trace拓扑：临时7轴，硬件轴7排除，力传感器从站1008") :
                       QStringLiteral("下发Lite Trace拓扑：标准8轴，力传感器从站1009"));
    }
    hardwareInterface.setLeadshineRatedMotorTorqueNm(ratedMotorTorqueNm);
    hardwareInterface.setMotorPara(motorIDVec, comType, {}, {}, {}, motorSlaveIdVec,
                                   motorTorqueVelocityLimitEnabled);
    appendItem(appliedItems,
               QStringLiteral("下发雷赛电机映射：逻辑轴数=%1，有效雷赛电机轴数=%2")
               .arg(ui->devAxisNum->value())
               .arg(usedHardwareAxis.size()));
    appendItem(appliedItems,
               QStringLiteral("下发雷赛转矩换算额定值：%1 N·m")
               .arg(QString::number(ratedMotorTorqueNm, 'f', 3)));
    const double torqueVelocityLimitRpm = motorTorqueServoVelocityLimitRpm();
    hardwareInterface.setLeadshineTorqueVelocityLimitRpm(torqueVelocityLimitRpm);
    appendItem(appliedItems,
               QStringLiteral("下发转矩模式速度限制：%1 rpm")
               .arg(QString::number(torqueVelocityLimitRpm, 'f', 3)));
    syncMotorSoftwareLimitsToHardware(appliedItems, skippedItems);
    if(writeConnectedAxisEquiv){
        if(!applyLeadshineAxisEquivFromUi()){
            return false;
        }
        appendItem(appliedItems, QStringLiteral("下发雷赛轴脉冲当量"));
    }
    else{
        std::vector<double> motorEquivVec(ui->devAxisNum->value(), 0.0);
        for(int axisIndex = 0; axisIndex < ui->devAxisNum->value(); ++axisIndex){
            if(isMotorAxis(axisIndex)){
                motorEquivVec[axisIndex] = configuredLeadshineAxisEquivForAxis(axisIndex);
            }
        }
        hardwareInterface.setLeadshineAxisEquiv(motorEquivVec);
        appendItem(skippedItems,
                   QStringLiteral("连接阶段不向任何轴写脉冲当量；仅缓存当前轴映射和当量"));
    }
    return true;
}

bool MainWindow::syncMotorSoftwareLimitsToHardware(QStringList* appliedItems,
                                                   QStringList* skippedItems)
{
    auto appendItem = [](QStringList* items, const QString& item){
        if(items && !item.isEmpty() && !items->contains(item)){
            items->append(item);
        }
    };

    if(runtimeState.systemRunning){
        appendItem(skippedItems, QStringLiteral("电机软件限位下发（系统运行中）"));
        return false;
    }

    const int axisCount = ui->devAxisNum->value();
    std::vector<double> minPos(axisCount, 0.0);
    std::vector<double> maxPos(axisCount, 0.0);
    std::vector<double> maxVel(axisCount, 0.0);
    for(int i=0; i<axisCount; ++i){
        if(i < static_cast<int>(axisMotorMinVec.size()) && axisMotorMinVec[i]){
            minPos[i] = axisMotorMinVec[i]->value();
        }
        if(i < static_cast<int>(axisMotorMaxVec.size()) && axisMotorMaxVec[i]){
            maxPos[i] = axisMotorMaxVec[i]->value();
        }
        if(i < static_cast<int>(axisMotorVelMaxVec.size()) && axisMotorVelMaxVec[i]){
            maxVel[i] = axisMotorVelMaxVec[i]->value();
        }
    }

    if(minPos == lastSyncedMotorSoftwareMinPos &&
            maxPos == lastSyncedMotorSoftwareMaxPos &&
            maxVel == lastSyncedMotorSoftwareMaxVel){
        appendItem(skippedItems, QStringLiteral("电机软件限位下发（最小位置、最大位置、最大速度与上次一致）"));
        return false;
    }

    hardwareInterface.setMotorSoftwareLimits(minPos, maxPos, maxVel);
    lastSyncedMotorSoftwareMinPos = minPos;
    lastSyncedMotorSoftwareMaxPos = maxPos;
    lastSyncedMotorSoftwareMaxVel = maxVel;
    appendItem(appliedItems,
               QStringLiteral("下发电机软件限位：轴数=%1，包含最小位置、最大位置、最大速度")
               .arg(axisCount));
    return true;
}

double MainWindow::configuredLeadshineAxisEquivForAxis(int axisIndex) const
{
    if(!isMotorAxis(axisIndex)){
        return 0.0;
    }

    if(isLinearMotorAxis(axisIndex)){
        return kLinearModuleAxisEquivPulsePerRevolution;
    }

    double baseEquiv = 1000.0;
    if(ui->devMotorFeedbackIsRd->isChecked()){
        baseEquiv *= kDegreesPerRevolution;
    }
    return baseEquiv;
}

bool MainWindow::applyLeadshineAxisEquivFromUi()
{
    if(!ui->devUseLS->isChecked()){
        return true;
    }
    if(hardwareInterface.isLSConnected() &&
            runtimeState.hardwareRunState == HardwareRunState::SingleAxisCommissioning){
        displayInfo("错误：Lite 单轴调试中禁止批量更新轴当量，请重新下发当前轴参数", "error");
        return false;
    }

    std::vector<double> motorEquivVec(ui->devAxisNum->value(), 0.0);
    bool hasLeadshineAxis = false;
    for(int i=0;i<ui->devAxisNum->value();++i){
        if(!isMotorAxis(i)){
            continue;
        }

        hasLeadshineAxis = true;
        const double axisEquiv = configuredLeadshineAxisEquivForAxis(i);
        if(axisEquiv <= 0.0){
            displayInfo(QStringLiteral("错误：%1未生成有效脉冲当量").arg(motorAxisDisplayName(i)).toStdString(), "error");
            return false;
        }
        motorEquivVec[i] = axisEquiv;
    }

    if(!hasLeadshineAxis){
        return true;
    }

    hardwareInterface.setLeadshineAxisEquiv(motorEquivVec);
    if(hardwareInterface.isLSConnected() && !hardwareInterface.applyLeadshineAxisEquiv()){
        displayInfo("错误：更新雷赛轴脉冲当量失败", "error");
        return false;
    }
    return true;
}

void MainWindow::delay(unsigned int msec){
    QTime _Timer = QTime::currentTime().addMSecs(msec);
    while( QTime::currentTime() < _Timer ){
        refreshSafetyMonitorHeartbeat();
        QCoreApplication::processEvents(QEventLoop::AllEvents, 100);// 处理本线程的事件循环，处理事件循环最多100ms必须返回本语句。可以防止线程阻塞
    }
    refreshSafetyMonitorHeartbeat();
}

bool MainWindow::togglePauseResumeFromUi()
{
    if(runtimeState.mainPauseSpeedZeroActive && !controlBoxSpeedZeroPvtReturnState.valid){
        runtimeState.mainPauseSpeedZeroActive = false;
    }
    const bool mainPauseSpeedZeroActive =
            runtimeState.mainPauseSpeedZeroActive &&
            controlBoxSpeedZeroPvtReturnState.valid;
    const bool mainPauseResumeRequested =
            mainPauseSpeedZeroActive &&
            (controlBoxSpeedZeroPvtReturnState.speedZeroResumeRequested ||
             controlBoxSpeedZeroPvtReturnState.speedZeroResumeStartInProgress);
    const RobotStateSnapshot robotState = currentRobotState(!mainPauseSpeedZeroActive);

    if(runtimeState.safetyFaultLatched &&
            !mainPauseSpeedZeroActive &&
            robotState.positionMotionState != PositionMotionState::PausedPvt){
        showPrimaryOperationFeedback(QStringLiteral("主控反馈：暂停按钮已按下，但当前存在安全锁存故障，请先复位"),
                                     QStringLiteral("warning"));
        refreshRunModeUiState();
        return false;
    }

    if(mainPauseResumeRequested){
        showPrimaryOperationFeedback(QStringLiteral("主控反馈：已请求继续，正在等待回到触发点后自动续跑"),
                                     QStringLiteral("warning"));
        refreshRunModeUiState();
        return false;
    }

    if(mainPauseSpeedZeroActive){
        if(!ui->devUseLS->isChecked() || !hardwareInterface.isLSConnected()){
            showPrimaryOperationFeedback(QStringLiteral("主控反馈：继续失败，当前未连接雷赛控制卡"),
                                         QStringLiteral("error"));
            return false;
        }

        QString failureReason;
        const bool released = releaseSpeedZeroControlledStop(&failureReason);
        if(released){
            const bool speedZeroStateStillValid =
                    controlBoxSpeedZeroPvtReturnState.valid;
            const bool resumePending =
                    speedZeroStateStillValid &&
                    (controlBoxSpeedZeroPvtReturnState.speedZeroResumeRequested ||
                     controlBoxSpeedZeroPvtReturnState.speedZeroResumeStartInProgress);
            runtimeState.mainPauseSpeedZeroActive = speedZeroStateStillValid;
            const QString feedbackType =
                    (speedZeroStateStillValid && !resumePending) ?
                        QStringLiteral("warning") :
                        QStringLiteral("info");
            showPrimaryOperationFeedback(resumePending ?
                                             QStringLiteral("主控反馈：已请求继续，回到触发点后自动续跑") :
                                             (speedZeroStateStillValid ?
                                                  QStringLiteral("主控反馈：继续请求未完成，请查看前面的提示") :
                                                  QStringLiteral("主控反馈：已释放速度置零并触发续跑")),
                                         feedbackType);
            refreshRunModeUiState();
        }
        else{
            showPrimaryOperationFeedback(QStringLiteral("主控反馈：继续失败，%1")
                                         .arg(failureReason.isEmpty() ?
                                                  QStringLiteral("当前没有由暂停按钮触发的速度置零状态") :
                                                  failureReason),
                                         QStringLiteral("warning"));
        }
        return released;
    }

    if(robotState.positionMotionState == PositionMotionState::ExecutingOnlineVelocity){
        stopOnlineVelocityTest(false, QStringLiteral("主界面暂停按钮请求减速停止"));
        showPrimaryOperationFeedback(
                    QStringLiteral("主控反馈：在线速度轨迹已减速停止；当前版本不支持从中断点继续，请重新规划下一段轨迹"),
                    QStringLiteral("warning"));
        return true;
    }

    if(robotState.positionMotionState == PositionMotionState::PausedPvt){
        if(!ui->devUseLS->isChecked() || !hardwareInterface.isLSConnected()){
            showPrimaryOperationFeedback(QStringLiteral("主控反馈：继续失败，当前未连接雷赛控制卡"),
                                         QStringLiteral("error"));
            return false;
        }

        bool resumed = false;
        if(pvtExecutionWorker){
            invokeOnObjectThreadWithHeartbeat(pvtExecutionWorker, [&](){
                resumed = pvtExecutionWorker->resumePvtMotion();
            }, [this](){
                refreshSafetyMonitorHeartbeat();
            });
        }
        if(resumed){
            showPrimaryOperationFeedback(QStringLiteral("主控反馈：已从暂停点继续位置轨迹"),
                                         QStringLiteral("info"));
            refreshRunModeUiState();
        }
        return resumed;
    }

    if(robotState.positionMotionState == PositionMotionState::ExecutingPvt){
        if(!ui->devUseLS->isChecked() || !hardwareInterface.isLSConnected()){
            showPrimaryOperationFeedback(QStringLiteral("主控反馈：暂停失败，当前未连接雷赛控制卡"),
                                         QStringLiteral("error"));
            return false;
        }

        QString failureReason;
        const bool paused = engageSpeedZeroControlledStop(&failureReason);
        if(paused){
            runtimeState.mainPauseSpeedZeroActive = true;
            showPrimaryOperationFeedback(QStringLiteral("主控反馈：已执行速度置零暂停，可点击“继续”续跑"),
                                         QStringLiteral("info"));
            refreshRunModeUiState();
        }
        else{
            showPrimaryOperationFeedback(QStringLiteral("主控反馈：暂停失败，%1")
                                         .arg(failureReason.isEmpty() ?
                                                  QStringLiteral("当前没有可暂停的运动源") :
                                                  failureReason),
                                         QStringLiteral("warning"));
        }
        return paused;
    }

    if(robotState.positionMotionState == PositionMotionState::Simulating){
        showPrimaryOperationFeedback(QStringLiteral("主控反馈：暂停按钮已按下，但当前轨迹仿真阶段暂不支持暂停/继续"),
                                     QStringLiteral("warning"));
        return false;
    }

    if(robotState.forceControlThreadRunning){
        showPrimaryOperationFeedback(QStringLiteral("主控反馈：暂停按钮已按下，但当前仅支持位置轨迹暂停/继续"),
                                     QStringLiteral("warning"));
        return false;
    }

    if(!ui->devUseLS->isChecked() || !hardwareInterface.isLSConnected()){
        showPrimaryOperationFeedback(QStringLiteral("主控反馈：暂停按钮已按下，但当前未连接雷赛控制卡，也没有可暂停轨迹"),
                                     QStringLiteral("warning"));
        return false;
    }

    showPrimaryOperationFeedback(QStringLiteral("主控反馈：暂停按钮已按下，但当前没有可暂停或继续的运动任务"),
                                 QStringLiteral("warning"));
    return false;
}

bool MainWindow::motorStop(){
    if(trajectoryCheckTimer){
        trajectoryCheckTimer->stop();
    }
    if(kEnablePosePvtTraceCommandFileOutput){
        samplePosePvtTraceCommandComparison();
    }
    if(kEnablePosePvtTraceCommandFileOutput){
        writePosePvtTraceCommandComparisonFile(QStringLiteral("manual_stop"), true);
    }
    cancelCircularContinuousMotionRestart();
    resetTrajectoryFileProgramBatchState();
    clearCableBreakPhysicalSimulationState();
    runtimeState.autoExecutePoseAfterSimulation = false;
    udpProgramControlExternalTrajectoryActive = false;
    clearUdpReturnHomeState();
    if(runtimeState.motorTorqueDebugActive){
        stopMotorTorqueDebug();
    }
    if(runtimeState.jogFollowTestActive || jogFollowTestRunning){
        stopJogFollowTest(QStringLiteral("manual_stop"), false);
    }
    if(runtimeState.onlineVelocityControlActive){
        stopOnlineVelocityTest(false, QStringLiteral("主停止按钮请求减速停止"));
    }
    else{
        invalidateOnlineVelocityPreparedPlan(QStringLiteral("主停止按钮已按下"), false);
    }

    ui->mainFCThread->setChecked(false);
    for(int i=0;i<useFCBtnVec.size();++i){
        useFCBtnVec[i]->setChecked(false);
    }
    clearHybridPoseForceModeState(true);

    if(simulationWorker){
        simulationWorker->stopPositionSimulation();
    }
    positionSimulationModel = nullptr;
    const bool hadLinearModuleTraceRecoveryPvt = runtimeState.linearModuleTraceRecoveryPvtActive;
    const bool hadLinearModuleHeightMove = runtimeState.linearModuleHeightMoveActive;
    const std::vector<int> linearModuleStopAxes =
            runtimeState.linearModuleHeightMoveAxis.empty() ?
                configuredLinearModuleAxisIndices() :
                runtimeState.linearModuleHeightMoveAxis;
    runtimeState.posModeRunning = false;
    runtimeState.pvtCommandActive = false;
    clearPvtMotionProtection();
    clearSingleMotorPointMoveState();
    clearLinearModuleHeightMoveState();
    if(hadLinearModuleTraceRecoveryPvt){
        hardwareInterface.clearPvtTrajectoryState();
    }
    runtimeState.cableHomeState = CableHomeState::Unconfirmed;
    lastTrajEndMotorTheta.clear();
    activePosModeMotorIndex.clear();
    activePosModeStartMotorTheta.clear();
    activePosModeContinuousStartMotorTheta.clear();
    runtimeState.controlBoxPausedPvtMotion = false;
    runtimeState.controlBoxPausedForceControl = false;
    runtimeState.mainPauseSpeedZeroActive = false;
    clearPoseTrajectoryDisplayState(true);
    hardwareInterface.clearPvtTrajectoryState();
    runtimeState.pvtCommandActive = false;
    clearPvtMotionProtection();

    ui->mainPosModeSwitch->setEnabled(true);
    setPoseSimulationIdleText(ui);
    ui->mainPosModeSend->setEnabled(true);
    ui->mainReplay3DViewer->setEnabled(true);
    setForceControlSelectionEnabled(true);
    updateCableHomeConfirmEnabled();
    ui->mainStopSwitch->setText("停止");

    if(!ui->devUseLS->isChecked() || !hardwareInterface.isLSConnected()){
        displayInfo("错误：雷赛控制卡未连接，无法下发电机停止指令", "error");
        return false;
    }

    bool stopOk = true;
    for(int i=0;i<ui->devAxisNum->value();++i){
        if(isMotorAxis(i)){
            stopOk = hardwareInterface.motorStop(i) && stopOk;
        }
    }
    if(stopOk){
        saveLinearModuleTraceRecoveryWindow(hadLinearModuleTraceRecoveryPvt ?
                                                QStringLiteral("manual_stop_linear_module_trace_recovery") :
                                                QStringLiteral("manual_stop"),
                                            false);
        if(hadLinearModuleHeightMove){
            disableLinearModuleMotors(linearModuleStopAxes, false);
        }
        displayInfo("按钮停止：已停止所有电机并清理运行状态");
    }
    return stopOk;
}

bool MainWindow::stopMotionFromControlBox(){
    const RobotStateSnapshot robotState = currentRobotState();
    if(runtimeState.jogFollowTestActive || jogFollowTestRunning){
        stopJogFollowTest(QStringLiteral("control_box_stop"), true);
        return true;
    }
    if(runtimeState.onlineVelocityControlActive){
        stopOnlineVelocityTest(false, QStringLiteral("控制盒请求减速停止"));
        return true;
    }
    const bool pvtTrajectoryExecuting =
            robotState.pvtTrajectoryAvailable &&
            robotState.pvtMotionRunning &&
            !robotState.pvtMotionPaused &&
            !robotState.pvtMotionFinished;
    if(!pvtTrajectoryExecuting){
        displayInfo("控制盒：运动控制停止仅在PVT轨迹执行中有效，当前轨迹未运行或已执行完成，不执行回点/归位逻辑", "warning");
        return true;
    }
    QString speedLimitReason;
    if(!controlBoxStopSpeedLimitAllowsAction(&speedLimitReason)){
        displayInfo(QStringLiteral("控制盒：运动控制停止无效，%1")
                    .arg(speedLimitReason)
                    .toStdString(),
                    "error");
        return false;
    }
    runtimeState.autoExecutePoseAfterSimulation = false;
    udpProgramControlExternalTrajectoryActive = false;
    clearUdpReturnHomeState();
    cancelCircularContinuousMotionRestart();
    resetTrajectoryFileProgramBatchState();
    const bool hasPositionTrajectory = robotState.posModeRunning ||
            robotState.pvtMotionRunning ||
            robotState.pvtMotionPaused ||
            (robotState.pvtTrajectoryAvailable && !robotState.pvtMotionFinished);
    const bool hasTorqueDebug = runtimeState.motorTorqueDebugActive;
    const bool hasSingleMotorPointMove = runtimeState.singleMotorPointMoveActive;
    const bool hasLinearModuleHeightMove = runtimeState.linearModuleHeightMoveActive;
    const bool hasLinearModuleTraceRecoveryPvt = runtimeState.linearModuleTraceRecoveryPvtActive;
    const bool hasPrimaryPositionTrajectory =
            pvtTrajectoryExecuting &&
            !hasLinearModuleTraceRecoveryPvt;
    std::vector<int> linearModuleStopAxes;

    if(!hasPositionTrajectory && !hasTorqueDebug &&
            !hasSingleMotorPointMove &&
            !hasLinearModuleHeightMove){
        displayInfo("当前没有运行中的位置轨迹或力控轨迹，停止指令不执行");
        return true;
    }

    if(trajectoryCheckTimer){
        trajectoryCheckTimer->stop();
    }
    if(kEnablePosePvtTraceCommandFileOutput){
        samplePosePvtTraceCommandComparison();
    }
    if(!hasPrimaryPositionTrajectory){
        if(kEnablePosePvtTraceCommandFileOutput){
            writePosePvtTraceCommandComparisonFile(QStringLiteral("control_box_stop"), true);
        }
    }
    cancelCircularContinuousMotionRestart();

    if(hasTorqueDebug){
        stopMotorTorqueDebug();
    }
    if(hasSingleMotorPointMove &&
            runtimeState.singleMotorPointMoveAxis >= 0 &&
            ui->devUseLS->isChecked() &&
            hardwareInterface.isLSConnected()){
        hardwareInterface.motorStop(runtimeState.singleMotorPointMoveAxis);
    }
    if(hasLinearModuleHeightMove &&
            ui->devUseLS->isChecked() &&
            hardwareInterface.isLSConnected()){
        linearModuleStopAxes = runtimeState.linearModuleHeightMoveAxis.empty() ?
                    configuredLinearModuleAxisIndices() :
                    runtimeState.linearModuleHeightMoveAxis;
        for(const int axisIndex : linearModuleStopAxes){
            hardwareInterface.motorStop(axisIndex);
        }
        if(hasLinearModuleTraceRecoveryPvt){
            hardwareInterface.clearPvtTrajectoryState();
        }
    }

    ui->mainFCThread->setChecked(false);
    for(int i=0;i<useFCBtnVec.size();++i){
        useFCBtnVec[i]->setChecked(false);
    }
    clearHybridPoseForceModeState(true);

    if(simulationWorker){
        simulationWorker->stopPositionSimulation();
    }
    positionSimulationModel = nullptr;
    if(!hasPrimaryPositionTrajectory){
        runtimeState.posModeRunning = false;
        runtimeState.pvtCommandActive = false;
        clearPvtMotionProtection();
    }
    clearSingleMotorPointMoveState();
    clearLinearModuleHeightMoveState();
    if(hasLinearModuleHeightMove){
        saveLinearModuleTraceRecoveryWindow(hasLinearModuleTraceRecoveryPvt ?
                                                QStringLiteral("control_box_stop_linear_module_trace_recovery") :
                                                QStringLiteral("control_box_stop_linear_module_height"),
                                            false);
        disableLinearModuleMotors(linearModuleStopAxes, false);
    }
    ui->mainPosModeSwitch->setEnabled(true);
    setPoseSimulationIdleText(ui);
    ui->mainPosModeSend->setEnabled(true);
    ui->mainReplay3DViewer->setEnabled(true);

    if(hasPrimaryPositionTrajectory){
        if(!ui->devUseLS->isChecked() || !hardwareInterface.isLSConnected()){
            displayInfo("错误：控制盒运动控制停止需要雷赛控制卡连接，无法执行停止和归位轨迹", "error");
            return false;
        }

        QString stopReturnFailure;
        if(!stopControlBoxActivePvtAndStartReturn(true, &stopReturnFailure)){
            if(!stopReturnFailure.isEmpty()){
                displayInfo(QStringLiteral("错误：控制盒运动控制停止失败，%1")
                            .arg(stopReturnFailure)
                            .toStdString(),
                            "error");
            }
            return false;
        }

        if(kEnablePosePvtTraceCommandFileOutput){
            writePosePvtTraceCommandComparisonFile(QStringLiteral("control_box_stop"), true);
        }

        if(controlBoxSpeedZeroPvtReturnState.autoReturnBlocked){
            const QString stopPointDiagnostic = controlBoxStopPointDiagnosticText();
            invokeOnObjectThreadWithHeartbeat(&hardwareInterface, [&](){
                hardwareInterface.freezeMotorTracePositionWindowRecording();
                hardwareInterface.clearPvtTrajectoryState();
            }, [this](){
                refreshSafetyMonitorHeartbeat();
            });
            runtimeState.controlBoxPausedPvtMotion = false;
            runtimeState.pvtCommandActive = false;
            clearPvtMotionProtection();
            updateControlWorkerConfig();
            updateSafetyMonitorConfig();
            displayInfo(QStringLiteral("控制盒：运动控制停止已按停止按钮逻辑停下，但自动回到停止点和后续归位已取消；%1")
                        .arg(stopPointDiagnostic)
                        .toStdString(),
                        "warning");
            clearControlBoxSpeedZeroPvtReturnState();
            return true;
        }

        if(controlBoxSpeedZeroPvtReturnState.returnPvtActive){
            displayInfo("控制盒：运动控制停止已按停止按钮逻辑停下，正在回到停止触发点，随后自动执行10s归位轨迹", "warning");
        }
        else{
            displayInfo("控制盒：运动控制停止已按停止按钮逻辑停下，已直接开始执行10s归位轨迹", "warning");
        }
        return true;
    }

    bool stopOk = true;
    if(!ui->devUseLS->isChecked() || !hardwareInterface.isLSConnected()){
        displayInfo("警告：雷赛控制卡未连接，仅清理软件轨迹状态，无法下发电机停止指令", "warning");
    }
    else if(hasPositionTrajectory && !hasLinearModuleTraceRecoveryPvt){
        stopOk = false;
        if(pvtExecutionWorker){
            beginHardwareExclusiveSnapshotTimeout(kHardwareExclusiveSnapshotTimeoutMs);
            invokeOnObjectThreadWithHeartbeat(pvtExecutionWorker, [&](){
                stopOk = pvtExecutionWorker->pausePvtMotion();
                pvtExecutionWorker->clearPvtState();
            }, [this](){
                refreshSafetyMonitorHeartbeat();
            });
            endHardwareExclusiveSnapshotTimeout();
        }
    }
    lastTrajEndMotorTheta.clear();
    std::vector<double> savedStartTheta = activePosModeStartMotorTheta;
    std::vector<int> savedMotorIndex = activePosModeMotorIndex;
    activePosModeStartMotorTheta.clear();
    activePosModeContinuousStartMotorTheta.clear();
    runtimeState.cableHomeState = CableHomeState::Unconfirmed;
    runtimeState.controlBoxPausedPvtMotion = false;
    runtimeState.controlBoxPausedForceControl = false;
    clearPoseTrajectoryDisplayState(true);
    setForceControlSelectionEnabled(true);
    updateCableHomeConfirmEnabled();
    ui->mainStopSwitch->setText("停止");

    if(!stopOk){
        return false;
    }

    if(hasPositionTrajectory && !savedStartTheta.empty() && !savedMotorIndex.empty() && ui->devUseLS->isChecked() && hardwareInterface.isLSConnected()){
        displayInfo("轨迹已暂停，电机将缓慢返回本段轨迹起始点...");
        QTimer::singleShot(100, this, [this, savedStartTheta, savedMotorIndex](){
            returnMotorAxesToStart(savedMotorIndex, savedStartTheta);
        });
    }

    return true;
}

void MainWindow::returnMotorAxesToStart(const std::vector<int>& motorIndex, const std::vector<double>& targetTheta){
    if(motorIndex.size() != targetTheta.size() || motorIndex.empty()){
        displayInfo("错误：回轨迹起始点参数无效", "error");
        return;
    }
    if(!ui->devUseLS->isChecked() || !hardwareInterface.isLSConnected()){
        displayInfo("警告：雷赛控制卡未连接，无法执行回轨迹起始点", "warning");
        return;
    }
    delay(100);
    const std::vector<double> motorHome = hardwareInterface.getAllMotorHome();
    for(size_t i=0;i<motorIndex.size();++i){
        const int idx = motorIndex[i];
        double relativeTarget = targetTheta[i];
        if(idx >= 0 && idx < static_cast<int>(motorHome.size())){
            relativeTarget -= motorHome[idx];
        }
        const double curPos = hardwareInterface.readMotorCurPos(idx);
        const double vel = std::max(std::fabs(targetTheta[i] - curPos) / 15.0, 1e-5);
        QString limitError;
        if(!validateMotorCommandLimits(idx,
                                       relativeTarget,
                                       vel,
                                       QStringLiteral("回轨迹起始点"),
                                       &limitError)){
            hardwareInterface.motorStop(idx);
            displayInfo(limitError.toStdString(), "error");
            return;
        }
    }

    bool moveOk = true;
    for(size_t i=0;i<motorIndex.size();++i){
        int idx = motorIndex[i];
        double curPos = hardwareInterface.readMotorCurPos(idx);
        double vel = std::fabs(targetTheta[i] - curPos) / 15.0;
        vel = std::max(std::fabs(vel), 1e-5);
        moveOk = hardwareInterface.motorAbsPos(idx, targetTheta[i], vel) && moveOk;
    }
    if(!moveOk){
        displayInfo("错误：回轨迹起始点时存在电机指令下发失败", "error");
        return;
    }
    displayInfo("电机正在返回本段轨迹起始点...");
}

bool MainWindow::motor2Home(){
    if(runtimeState.motorPositionLimitRecoveryActive){
        displayInfo(QStringLiteral("错误：电机回零启动失败，当前处于电机位置超限恢复状态，恢复轴=%1。请先使用全绳力控、力矩模式、单电机点位或JOG跟随测试将电机恢复到软件限位内。")
                    .arg(motorPositionLimitRecoveryAxisText(runtimeState.motorPositionLimitRecoveryAxes))
                    .toStdString(),
                    "error");
        return false;
    }
    if(trajectoryCheckTimer){
        trajectoryCheckTimer->stop();
    }
    cancelCircularContinuousMotionRestart();
    clearCableBreakPhysicalSimulationState();
    HybridPoseForceModeConfig hybridHomingConfig;
    const bool hybridHomingRequested = isHybridPoseForceModeRequested();
    if(hybridHomingRequested){
        QString hybridModeError;
        if(!buildHybridPoseForceModeConfig(hybridHomingConfig, hybridModeError) ||
                !hybridHomingConfig.enabled){
            displayInfo(QStringLiteral("错误：零位校准1启动失败，力位混合配置无效：%1")
                        .arg(hybridModeError.isEmpty() ?
                                 QStringLiteral("请先选择两根力控绳索") :
                                 hybridModeError)
                        .toStdString(),
                        "error");
            return false;
        }
    }
    const bool keepPositionContinuousForHoming =
            ui->Poscontinuetraj->isChecked() &&
            calibrationWorkflowStage != CalibrationWorkflowStage::MechanicalHoming;
    const bool keepCableHomeForContinuousHoming =
            keepPositionContinuousForHoming &&
            runtimeState.cableHomeState == CableHomeState::Confirmed;
    if(keepPositionContinuousForHoming){
        optionalCheckBoxSetChecked(this, "Forcecontinuetraj", false);
    }
    else{
        resetContinuousTrajectoryOptions();
    }
    if(!keepCableHomeForContinuousHoming){
        runtimeState.cableHomeState = CableHomeState::Unconfirmed;
    }
    updateCableHomeConfirmEnabled();
    hardwareInterface.clearPvtTrajectoryState();
    runtimeState.pvtCommandActive = false;
    clearPvtMotionProtection();
    if(simulationWorker){
        simulationWorker->stopPositionSimulation();
    }
    positionSimulationModel = nullptr;
    runtimeState.posModeRunning = false;
    runtimeState.pvtCommandActive = false;
    clearPvtMotionProtection();
    clearSingleMotorPointMoveState();
    lastTrajEndMotorTheta.clear();
    activePosModeMotorIndex.clear();
    activePosModeStartMotorTheta.clear();
    activePosModeContinuousStartMotorTheta.clear();
    ui->mainPosModeSwitch->setEnabled(true);
    setPoseSimulationIdleText(ui);
    ui->mainPosModeSend->setEnabled(true);
    ui->mainReplay3DViewer->setEnabled(true);

    if(hybridHomingRequested){
        runtimeState.hybridPoseForceModeActive = true;
        activeHybridPoseForceConfig = hybridHomingConfig;
        activeHybridExpectedForceTraj.clear();
        activeHybridExpectedForcePointIndex = -1;
        if(controlWorker){
            controlWorker->clearExternalExpectedForce();
            controlWorker->setExternalExpectedForce(hybridHomingConfig.frozenExpectedForce);
        }
        if(ui->mainFCThread && !ui->mainFCThread->isChecked() &&
                !enableForceControlThreadIfExpectedForceReady(
                    QStringLiteral("机械回零保持力控线程"))){
            return false;
        }
        displayInfo("机械回零：力位混合模式保持开启，两段回零PVT将排除两根力控绳索");
    }
    else{
        ui->mainFCThread->setChecked(false);
        for(int i=0;i<useFCBtnVec.size();++i){
            useFCBtnVec[i]->setChecked(false);// 先取消所有力控
        }
        clearHybridPoseForceModeState(true);
    }
    setForceControlSelectionEnabled(true);
    if(hybridHomingRequested){
        requestImmediateForceControlUpdate();
        updateSafetyMonitorConfig();
        if(ccThread && ccThread->isRunning()){
            delay(std::max(20, ui->devCtrlCycleMs->value() * 2));
        }
    }
    else{
        delay(100);// 等待力控速度指令停止
    }
    if(keepCableHomeForContinuousHoming){
        displayInfo("机械回零：已保留连续轨迹选项和预紧零点，使用当前轨迹/缓存位姿作为回零轨迹起点");
    }

    if(ui->devUseLS->isChecked() && hardwareInterface.isLSConnected()){
        for(int i=0;i<ui->devAxisNum->value();++i){
            if(isMotorAxis(i)){
                hardwareInterface.motorStop(i);
            }
        }
        delay(50);
        if(!executeCalibrationMechanicalHoming(
                    QStringLiteral("机械回零"),
                    hybridHomingRequested ? &hybridHomingConfig : nullptr)){
            return false;
        }
    }
    else{
        displayInfo("错误：雷赛控制卡未连接，无法执行电机回零位", "error");
        return false;
    }
    return true;
}

double MainWindow::pretensionForceAllowedError(double expectedForce) const
{
    // const double thresholdRatio =
    //         std::max(0.0, ui->devFCDeadbandPercent->value()) / 100.0;
    const double thresholdRatio = 1;

    return std::max(std::fabs(expectedForce) * thresholdRatio, 0.1);
}

bool MainWindow::isZeroPosePretensionForceWithinTolerance(QString* errorMessage) const
{
    std::vector<bool> checkedSensor(axisForceSensorNum,false);
    bool hasValidSensor = false;

    for(int axisIndex=0; axisIndex<ui->devAxisNum->value(); ++axisIndex){
        if(!isModeledMotorAxis(axisIndex)){
            continue;
        }

        const int sensorIndex = axisSensorIndexVec[axisIndex]->value();
        if(sensorIndex < 0 || sensorIndex >= axisForceSensorNum || checkedSensor[sensorIndex]){
            continue;
        }
        if(sensorIndex >= static_cast<int>(mainForceSensorDataVal.size()) ||
                sensorIndex >= static_cast<int>(mainForceSensorExp.size())){
            return false;
        }

        checkedSensor[sensorIndex] = true;
        hasValidSensor = true;

        const double curForce = mainForceSensorDataVal[sensorIndex];
        const double expForce = mainForceSensorExp[sensorIndex]->value();
        if(!std::isfinite(curForce) || !std::isfinite(expForce)){
            if(errorMessage){
                *errorMessage = QStringLiteral("错误：零位预紧确认失败，绳索%1/传感器%2当前力或期望力无效")
                        .arg(axisIndex + 1)
                        .arg(sensorIndex + 1);
            }
            return false;
        }
        const double allowedErr = pretensionForceAllowedError(expForce);
        if(std::fabs(curForce - expForce) > allowedErr){
            if(errorMessage){
                *errorMessage = QStringLiteral("错误：零位预紧确认失败，绳索%1/传感器%2当前力%3 N，期望%4 N，误差%5 N超过阈值%6 N")
                        .arg(axisIndex + 1)
                        .arg(sensorIndex + 1)
                        .arg(curForce, 0, 'f', 3)
                        .arg(expForce, 0, 'f', 3)
                        .arg(std::fabs(curForce - expForce), 0, 'f', 3)
                        .arg(allowedErr, 0, 'f', 3);
            }
            return false;
        }
    }

    if(!hasValidSensor && errorMessage){
        *errorMessage = QStringLiteral("错误：零位预紧确认失败，当前没有有效建模绳索/张力传感器映射");
    }
    return hasValidSensor;
}

bool MainWindow::isRestoredRuntimePretensionForceWithinTolerance(QString* errorMessage) const
{
    if(!hasFinitePoseMatrix(restoredRuntimePretensionPlatformPose)){
        if(errorMessage){
            *errorMessage = QStringLiteral("错误：非零位预紧确认失败，未读取到有效的上次轨迹/估计位姿");
        }
        return false;
    }
    if(lastForceDistributionExpectedForce.empty()){
        if(errorMessage){
            *errorMessage = QStringLiteral("错误：非零位预紧确认失败，未读取到有效的上次力分配结果");
        }
        return false;
    }
    if(!isHybridPoseForceModeRequested()){
        if(errorMessage){
            *errorMessage = QStringLiteral("错误：非零位预紧确认失败，请先打开力位混合控制模式并选择两根绳索");
        }
        return false;
    }

    HybridPoseForceModeConfig hybridConfig;
    QString hybridError;
    if(!buildHybridPoseForceModeConfig(hybridConfig, hybridError) || !hybridConfig.enabled){
        if(errorMessage){
            *errorMessage = hybridError.isEmpty() ?
                        QStringLiteral("错误：非零位预紧确认失败，请先选择两根力控绳索") :
                        QStringLiteral("错误：非零位预紧确认失败，%1").arg(hybridError);
        }
        return false;
    }

    for(int sensorIndex : hybridConfig.forceSensorIndex){
        if(sensorIndex < 0 ||
                sensorIndex >= static_cast<int>(mainForceSensorDataVal.size()) ||
                sensorIndex >= static_cast<int>(lastForceDistributionExpectedForce.size())){
            if(errorMessage){
                *errorMessage = QStringLiteral("错误：非零位预紧确认失败，所选传感器%1缺少当前力或历史力分配期望值")
                        .arg(sensorIndex + 1);
            }
            return false;
        }

        const double curForce = mainForceSensorDataVal[sensorIndex];
        const double expForce = lastForceDistributionExpectedForce[sensorIndex];
        const double allowedErr = pretensionForceAllowedError(expForce);
        if(!std::isfinite(curForce) || !std::isfinite(expForce)){
            if(errorMessage){
                *errorMessage = QStringLiteral("错误：非零位预紧确认失败，所选传感器%1当前力或历史期望力无效")
                        .arg(sensorIndex + 1);
            }
            return false;
        }
        if(std::fabs(curForce - expForce) > allowedErr){
            if(errorMessage){
                *errorMessage = QStringLiteral("错误：非零位预紧确认失败，传感器%1当前力%2 N，上次力分配期望%3 N，误差%4 N超过阈值%5 N")
                        .arg(sensorIndex + 1)
                        .arg(curForce, 0, 'f', 3)
                        .arg(expForce, 0, 'f', 3)
                        .arg(std::fabs(curForce - expForce), 0, 'f', 3)
                        .arg(allowedErr, 0, 'f', 3);
            }
            return false;
        }
    }

    return true;
}

bool MainWindow::isCableForceWithinHomeConfirmTolerance(QString* errorMessage) const
{
    if(runtimeState.pretensionMode == PretensionMode::RestoredRuntimePose){
        return isRestoredRuntimePretensionForceWithinTolerance(errorMessage);
    }
    return isZeroPosePretensionForceWithinTolerance(errorMessage);
}

bool MainWindow::shouldSkipCableHomeCheckForMotion(const QString& motionName) const{
    if(motionName == QStringLiteral("实时力控")){
        return optionalCheckBoxChecked(this, "Forcecontinuetraj", false);
    }

    return ui->Poscontinuetraj->isChecked();
}

void MainWindow::resetContinuousTrajectoryOptions(){
    ui->Poscontinuetraj->setChecked(false);
    optionalCheckBoxSetChecked(this, "Forcecontinuetraj", false);
    optionalCheckBoxSetChecked(this, "posTrajCircularContinuousMotion", false);
    cancelCircularContinuousMotionRestart();
}

bool MainWindow::ensureCableHomeReadyForMotion(const QString& motionName){
    if(runtimeState.cableHomeState == CableHomeState::Confirmed){
        return true;
    }

    if(shouldSkipCableHomeCheckForMotion(motionName)){
        return true;
    }

    runtimeState.cableHomeState = CableHomeState::WaitingForceStable;
    updateCableHomeConfirmEnabled();
    displayInfo(QString("错误：%1启动失败，请先完成预紧并点击“预紧确认”")
                    .arg(motionName)
                    .toStdString(), "error");
    return false;
}

void MainWindow::updateCableHomeConfirmEnabled(){
    const bool motionBlockingConfirm =
            runtimeState.posModeRunning ||
            runtimeState.pvtCommandActive ||
            calibrationWorkflowStage == CalibrationWorkflowStage::MechanicalHoming;
    const bool litePartialConnection =
            isLiteTemplateActive() &&
            !runtimeState.systemRunning &&
            runtimeState.hardwareRunState != HardwareRunState::Disconnected;
    const bool canConfirm = runtimeState.cableHomeState != CableHomeState::Confirmed &&
            !motionBlockingConfirm &&
            !litePartialConnection;
    ui->mainSetCableHome->setEnabled(canConfirm);
    refreshCalibrationUiState();
}

bool MainWindow::setCableHome(){
    if(isLiteTemplateActive() && !runtimeState.systemRunning &&
            runtimeState.hardwareRunState != HardwareRunState::Disconnected){
        displayInfo("错误：Lite 单轴调试连接中禁止执行整机预紧确认；请使用调试页的临时零点", "error");
        return false;
    }
    QString pretensionErrorMessage;
    if(!isCableForceWithinHomeConfirmTolerance(&pretensionErrorMessage)){
        runtimeState.cableHomeState = CableHomeState::WaitingForceStable;
        updateSafetyMonitorConfig();
        updateCableHomeConfirmEnabled();
        displayInfo((pretensionErrorMessage.isEmpty() ?
                     QStringLiteral("错误：预紧确认失败，当前绳索力与期望力误差超过设定阈值") :
                     pretensionErrorMessage).toStdString(),
                    "error");
        refreshCalibrationUiState();
        return false;
    }

    std::vector<double> currentMotorAbsPos = hardwareInterface.getAllMotorEncoderPosUnit();
    bool currentMotorAbsPosUsesEncoder = !currentMotorAbsPos.empty();
    QString trajectoryLookupSource = QStringLiteral("编码器");
    if(currentMotorAbsPos.empty()){
        currentMotorAbsPos = hardwareInterface.getAllMotorPosUnit();
        currentMotorAbsPosUsesEncoder = false;
        trajectoryLookupSource = QStringLiteral("电机位置反馈");
    }
    auto motorPositionMatchesSavedZero =
            [this, currentMotorAbsPosUsesEncoder](const std::vector<double>& absPos) -> bool {
        const std::vector<double>& savedZero =
                (currentMotorAbsPosUsesEncoder && !zeroMotorHomeEncoderPos.empty()) ?
                    zeroMotorHomeEncoderPos :
                    zeroMotorHomePos;
        if(!zeroMotorHomeReferenceLoaded ||
                savedZero.empty() ||
                absPos.empty()){
            return false;
        }
        const int axisCount = std::min({
                                           ui ? ui->devAxisNum->value() : static_cast<int>(savedZero.size()),
                                           static_cast<int>(savedZero.size()),
                                           static_cast<int>(absPos.size())
                                       });
        if(axisCount <= 0){
            return false;
        }
        for(int axisIndex=0; axisIndex<axisCount; ++axisIndex){
            if(!std::isfinite(absPos[axisIndex]) ||
                    !std::isfinite(savedZero[axisIndex]) ||
                    std::abs(absPos[axisIndex] - savedZero[axisIndex]) >
                    kZeroHomeEncoderMatchToleranceUnit){
                return false;
            }
        }
        return true;
    };

    const bool restoredRuntimePretension =
            runtimeState.pretensionMode == PretensionMode::RestoredRuntimePose &&
            hasFinitePoseMatrix(restoredRuntimePretensionPlatformPose);
    const bool zeroPosePretension =
            runtimeState.pretensionMode == PretensionMode::ZeroPose;

    const bool currentAtSavedZero = motorPositionMatchesSavedZero(currentMotorAbsPos);
    const bool defaultZeroPosePriorityForConfirm =
            zeroPosePretension;
    bool recoveredRuntimePretensionFromTrajectory = false;
    bool recoveredRuntimePretensionFromCompletedTrajectory = false;
    int recoveredTrajectoryPointIndex = -1;
    double recoveredTrajectoryRmsError = 0.0;
    double recoveredTrajectoryMaxError = 0.0;
    const bool hasSavedCurrentPoseForPretension =
            lastPlannedPoseTrajectoryEndPose.size() >= 6 &&
            hasFiniteValues(lastPlannedPoseTrajectoryEndPose, 6);
    if(!defaultZeroPosePriorityForConfirm &&
            zeroPosePretension &&
            !currentAtSavedZero &&
            hasSavedCurrentPoseForPretension &&
            !lastForwardKinematicsPoseLoadedFromSnapshot){
        recoveredRuntimePretensionFromCompletedTrajectory = true;
    }
    if(!recoveredRuntimePretensionFromCompletedTrajectory &&
            !defaultZeroPosePriorityForConfirm &&
            zeroPosePretension &&
            zeroMotorHomeReferenceLoaded &&
            !currentAtSavedZero &&
            !currentMotorAbsPos.empty() &&
            ensurePlannedPoseTrajectoryRuntimeRecordLoaded(false)){
        int pointIndex = -1;
        double rmsError = 0.0;
        double maxError = 0.0;
        if(findPlannedPoseTrajectoryPointByMotorPosition(currentMotorAbsPos,
                                                         pointIndex,
                                                         &rmsError,
                                                         &maxError) &&
                pointIndex >= 0 &&
                pointIndex < static_cast<int>(plannedPoseTrajectoryRecordPose.size())){
            recoveredRuntimePretensionFromTrajectory = true;
            recoveredTrajectoryPointIndex = pointIndex;
            recoveredTrajectoryRmsError = rmsError;
            recoveredTrajectoryMaxError = maxError;
        }
    }
    if(!recoveredRuntimePretensionFromTrajectory &&
            !defaultZeroPosePriorityForConfirm &&
            zeroPosePretension &&
            !currentAtSavedZero &&
            hasSavedCurrentPoseForPretension){
        recoveredRuntimePretensionFromCompletedTrajectory = true;
    }

    const bool runtimePosePretension =
            restoredRuntimePretension ||
            recoveredRuntimePretensionFromCompletedTrajectory ||
            recoveredRuntimePretensionFromTrajectory;
    if(restoredRuntimePretension){
        applyTrajectoryStartPoseToUi(restoredRuntimePretensionPlatformPose.front());
    }
    const std::vector<std::vector<double>> confirmedHomePose =
            defaultZeroPosePriorityForConfirm ?
                normalizedPoseMatrix(configuredCableHomePlatformPose()) :
            restoredRuntimePretension ?
                restoredRuntimePretensionPlatformPose :
            recoveredRuntimePretensionFromCompletedTrajectory ?
                std::vector<std::vector<double>>{
                    std::vector<double>(
                        lastPlannedPoseTrajectoryEndPose.begin(),
                        lastPlannedPoseTrajectoryEndPose.begin() + 6)
                } :
            recoveredRuntimePretensionFromTrajectory ?
                std::vector<std::vector<double>>{
                    plannedPoseTrajectoryRecordPose[recoveredTrajectoryPointIndex]
                } :
                configuredCableHomePlatformPose();
    if(defaultZeroPosePriorityForConfirm && hasFinitePoseMatrix(confirmedHomePose)){
        zeroMotorHomePlatformPose = normalizedPoseMatrix(confirmedHomePose);
        restoredRuntimePretensionPlatformPose.clear();
    }

    runtimeState.cableHomeState = CableHomeState::Confirmed;
    runtimeState.cableHomeConfirmedTimestampMs = QDateTime::currentMSecsSinceEpoch();
    resetCableKinematicVisualizationState();
    std::vector<double> cableHomeAbsPos = hardwareInterface.getAllMotorPosUnit();
    if(cableHomeAbsPos.empty()){
        cableHomeAbsPos = currentMotorAbsPos;
    }
    std::vector<double> cableHomeEncoderPos = hardwareInterface.getAllMotorEncoderPosUnit();
    if(cableHomeEncoderPos.empty() && currentMotorAbsPosUsesEncoder){
        cableHomeEncoderPos = currentMotorAbsPos;
    }
    const std::vector<qint64> cableHomeTraceCommandRawPulse =
            readCurrentTraceCommandRawPulseSnapshot();
    const bool keepStartupMotorHome = isLiteTemplateActive();
    std::vector<double> retainedMotorHome = cableHomeAbsPos;
    if(keepStartupMotorHome){
        retainedMotorHome = hardwareInterface.getAllMotorHome();
        if(retainedMotorHome.empty()){
            displayInfo("警告：Lite 预紧确认无法读取本次上电 motorHome；未覆盖电机零位", "warning");
        }
        else{
            displayInfo("Lite 预紧确认仅更新位姿/绳长参考，motorHome 继续保持本次上电位置");
        }
    }
    else{
        hardwareInterface.setMotorHome(cableHomeAbsPos);
        motorHomeUiCache = cableHomeAbsPos;
    }
    std::vector<double> retainedTrajectoryMotorBase;
    if(keepStartupMotorHome && !retainedMotorHome.empty()){
        bool baseValid = true;
        for(int endIndex = 0; endIndex < ui->devEndNum->value() && baseValid; ++endIndex){
            for(int axisIndex = 0; axisIndex < ui->devAxisNum->value(); ++axisIndex){
                if(!isModeledMotorAxis(axisIndex) ||
                        axisEndVec[axisIndex]->value() != endIndex){
                    continue;
                }
                if(axisIndex >= static_cast<int>(cableHomeAbsPos.size()) ||
                        axisIndex >= static_cast<int>(retainedMotorHome.size()) ||
                        !std::isfinite(cableHomeAbsPos[axisIndex]) ||
                        !std::isfinite(retainedMotorHome[axisIndex])){
                    baseValid = false;
                    break;
                }
                retainedTrajectoryMotorBase.push_back(
                            cableHomeAbsPos[axisIndex] - retainedMotorHome[axisIndex]);
            }
        }
        if(!baseValid || retainedTrajectoryMotorBase.empty()){
            retainedTrajectoryMotorBase.clear();
            displayInfo("警告：Lite 预紧确认无法生成当前位置相对上电 motorHome 的PVT起点基值", "warning");
        }
    }
    if(runtimePosePretension &&
            !cableHomeAbsPos.empty() &&
            hasFinitePoseMatrix(confirmedHomePose)){
        currentRuntimeMotorHomeReferenceLoaded = true;
        currentRuntimeMotorHomePos = retainedMotorHome;
        currentRuntimeMotorHomeEncoderPos = keepStartupMotorHome ?
                    std::vector<double>() : cableHomeEncoderPos;
        currentRuntimeReferenceMotorPos = cableHomeAbsPos;
        currentRuntimeReferenceMotorEncoderPos = cableHomeEncoderPos;
        currentRuntimeMotorHomePlatformPose = normalizedPoseMatrix(confirmedHomePose);
    }
    else{
        currentRuntimeMotorHomeReferenceLoaded = false;
        currentRuntimeMotorHomePos.clear();
        currentRuntimeMotorHomeEncoderPos.clear();
        currentRuntimeReferenceMotorPos.clear();
        currentRuntimeReferenceMotorEncoderPos.clear();
        currentRuntimeMotorHomePlatformPose.clear();
    }
    const bool shouldUpdateCalibratedZero =
            !keepStartupMotorHome &&
            zeroPosePretension &&
            !runtimePosePretension &&
            !cableHomeAbsPos.empty();
    if(shouldUpdateCalibratedZero){
        zeroMotorHomeReferenceLoaded = true;
        zeroMotorHomePos = cableHomeAbsPos;
        zeroMotorHomeEncoderPos = cableHomeEncoderPos;
        zeroMotorHomeTraceCommandRawPulse = cableHomeTraceCommandRawPulse;
        zeroMotorHomePlatformPose = normalizedPoseMatrix(confirmedHomePose);
        hardwareInterface.setMotorSafetyHomeEncoderUnit(cableHomeEncoderPos);
        hardwareInterface.setMotorSafetyHomeTraceCommandRawPulse(cableHomeTraceCommandRawPulse);
        saveZeroMotorHomeSnapshot(cableHomeAbsPos,
                                  false,
                                  zeroMotorHomePlatformPose,
                                  cableHomeEncoderPos,
                                  cableHomeTraceCommandRawPulse);
    }
    if(!cableHomeAbsPos.empty()){
        applyMotorPositionSnapshot(cableHomeAbsPos);
    }
    motorPosDisplayZero.clear();
    const std::vector<double> referenceCableHomePos =
            buildForwardKinematicsCableHomePosFromAxisValues(motorCurPos, true);
    if(!rebuildForwardKinematicsCableLengthCache(confirmedHomePose, referenceCableHomePos)){
        displayInfo("警告：预紧确认后正运动学绳长参考缓存生成失败，实际位姿曲线将使用后备绳长来源", "warning");
    }
    const bool recoveredCompletedPoseLoadedFromSnapshot =
            recoveredRuntimePretensionFromCompletedTrajectory &&
            lastForwardKinematicsPoseLoadedFromSnapshot;
    clearPoseTrajectoryDisplayState(false);
    lastForwardKinematicsPose.clear();
    lastForwardKinematicsPoseTimestampMs = -1;
    lastForwardKinematicsPoseLoadedFromSnapshot = false;

    if(recoveredRuntimePretensionFromCompletedTrajectory){
        cacheForwardKinematicsPose(confirmedHomePose);
        restoredRuntimePretensionPlatformPose = confirmedHomePose;
        applyTrajectoryStartPoseToUi(confirmedHomePose.front());
        refreshForwardKinematicsPoseDisplay();
        displayInfo(recoveredCompletedPoseLoadedFromSnapshot ?
                    "预紧确认：未能按编码器匹配保存轨迹，已沿用自动读取的保存当前位姿作为当前末端位姿和后续轨迹起点" :
                    "预紧确认：沿用上一段完整轨迹终点作为当前末端位姿和后续轨迹起点");
    }
    else if(recoveredRuntimePretensionFromTrajectory){
        activePoseTrajectoryDisplayTraj = plannedPoseTrajectoryDisplayTraj;
        activePoseTrajectoryDisplayTimeStamp = plannedPoseTrajectoryRecordTimeStamp;
        activePoseTrajectoryDisplayRunning = false;
        if(cachePoseTrajectoryDisplayPoint(recoveredTrajectoryPointIndex) &&
                !lastForwardKinematicsPose.empty()){
            restoredRuntimePretensionPlatformPose = lastForwardKinematicsPose;
            applyTrajectoryStartPoseToUi(lastForwardKinematicsPose.front());
            refreshForwardKinematicsPoseDisplay();
            displayInfo(QStringLiteral("预紧确认：当前%1匹配保存轨迹点 %2/%3，已恢复实时末端位姿作为后续轨迹起点；RMS误差=%4，最大误差=%5")
                        .arg(trajectoryLookupSource)
                        .arg(recoveredTrajectoryPointIndex + 1)
                        .arg(static_cast<int>(plannedPoseTrajectoryRecordPose.size()))
                        .arg(recoveredTrajectoryRmsError, 0, 'f', 6)
                        .arg(recoveredTrajectoryMaxError, 0, 'f', 6)
                        .toStdString());
        }
    }
    else if(defaultZeroPosePriorityForConfirm){
        cacheForwardKinematicsPose(confirmedHomePose);
        if(!confirmedHomePose.empty() &&
                confirmedHomePose.front().size() >= 6){
            applyTrajectoryStartPoseToUi(confirmedHomePose.front());
            refreshForwardKinematicsPoseDisplay();
            displayInfo("预紧确认：已优先使用默认零点位姿刷新轨迹/估计末端位姿和后续轨迹起点");
        }
    }
    else if(!ui->devUseCamForActPose->isChecked()){
        cacheForwardKinematicsPose(confirmedHomePose);
    }

    ui->mainFCThread->setChecked(false);
    ui->mainAllUseFC->setChecked(false);
    allUseFC(false);
    setForceControlSelectionEnabled(true);
    if(ui->devUseLS->isChecked() && hardwareInterface.isLSConnected()){
        for(int i=0;i<ui->devAxisNum->value();++i){
            if(isMotorAxis(i)){
                hardwareInterface.motorStop(i);
            }
        }
    }

    if(keepStartupMotorHome){
        lastTrajEndMotorTheta = retainedTrajectoryMotorBase;
    }
    else{
        lastTrajEndMotorTheta.clear();
    }
    if(runtimePosePretension && !confirmedHomePose.empty() &&
            confirmedHomePose.front().size() >= 6){
        lastPlannedPoseTrajectoryEndPose.assign(
                    confirmedHomePose.front().begin(),
                    confirmedHomePose.front().begin() + 6);
    }
    else{
        lastPlannedPoseTrajectoryEndPose.clear();
    }
    activePosModeMotorIndex.clear();
    activePosModeStartMotorTheta.clear();
    activePosModeContinuousStartMotorTheta.clear();
    runtimeState.controlBoxPausedPvtMotion = false;
    runtimeState.controlBoxPausedForceControl = false;
    runtimeState.mainPauseSpeedZeroActive = false;

    ui->mainSetCableHome->setEnabled(false);
    ui->mainPosModeSwitch->setEnabled(true);
    calibrationWorkflowStage = CalibrationWorkflowStage::Completed;
    if(ui->Poscontinuetraj && !ui->Poscontinuetraj->isChecked()){
        ui->Poscontinuetraj->setChecked(true);
        displayInfo("预紧确认：已自动勾选连续轨迹，下一次轨迹规划将默认使用当前确认位姿作为连续起点");
    }
    updateControlWorkerConfig();
    updateSafetyMonitorConfig();
    bool calibrationRecordSaved = true;
    if(runtimePosePretension){
        saveLastRuntimeResultSnapshot(false);
    }
    else{
        saveLastRuntimeResultSnapshot(false);
        if(shouldUpdateCalibratedZero){
            // 确认零位属于运行状态，必须保存至新版正式路径，供下次启动和
            // “恢复最近零位校准”直接使用；不再让临时导出目录取代该记录。
            calibrationRecordSaved =
                    saveCalibrationSnapshotRecordSetToDir(calibrationStorageDirPath(), true);
        }
    }
    if(runtimePosePretension){
        displayInfo("非零位预紧确认完成：已将上次运行位姿作为当前末端位姿，记录当前电机位置为绳索/轨迹零点并刷新轨迹/估计位姿");
    }
    else if(!calibrationRecordSaved){
        displayInfo("零位校准已完成，但校准记录保存失败；当前候选校准状态仍保留，请检查 data/calibration_records 的写入权限后重新保存记录", "warning");
    }
    else{
        displayInfo("零位校准完成：已记录当前电机位置为绳索/轨迹零点，力控已关闭，系统处于可运行状态");
    }
    refreshCalibrationUiState();
    refreshRunModeUiState();
    return true;
}

void MainWindow::allUseFC(bool isChecked){
    if(suppressForceControlSelectionSideEffects){
        return;
    }
    if(isHybridPoseForceModeRequested()){
        if(ui->mainAllUseFC->isChecked()){
            const QSignalBlocker blocker(ui->mainAllUseFC);
            ui->mainAllUseFC->setChecked(false);
        }
        enforceHybridPoseForceSelectionLimit();
        return;
    }
    if(isSingleCableForceDebugModeActive()){
        if(ui->mainAllUseFC->isChecked()){
            const QSignalBlocker blocker(ui->mainAllUseFC);
            ui->mainAllUseFC->setChecked(false);
        }
        enforceSingleCableForceSelection();
        return;
    }
    const bool previousSuppress = suppressForceControlSelectionSideEffects;
    suppressForceControlSelectionSideEffects = true;
    for(int i=0;i<useFCBtnVec.size();++i){
        if(useFCBtnVec[i]){
            const QSignalBlocker blocker(useFCBtnVec[i]);
            useFCBtnVec[i]->setChecked(isChecked);
        }
    }
    suppressForceControlSelectionSideEffects = previousSuppress;
    if(isChecked){
        if(ui->mainFCThread && ui->mainFCThread->isChecked() &&
                !ensureForceControlExpectedForceReady(QStringLiteral("完全力控启动"))){
            suppressForceControlSelectionSideEffects = true;
            if(ui->mainAllUseFC){
                const QSignalBlocker allUseBlocker(ui->mainAllUseFC);
                ui->mainAllUseFC->setChecked(false);
            }
            for(QRadioButton* btn : useFCBtnVec){
                if(btn){
                    const QSignalBlocker blocker(btn);
                    btn->setChecked(false);
                }
            }
            suppressForceControlSelectionSideEffects = false;
            cancelManualForceControlPretensionRamp(true);
            requestImmediateForceControlUpdate();
            return;
        }
        startManualForceControlPretensionRampForCurrentSelection();
    }
    else{
        cancelManualForceControlPretensionRamp(true);
    }
    requestImmediateForceControlUpdate();
}



void MainWindow::camLock(bool lockCam){
    ui->mainResetMotiveFit->setEnabled(lockCam);
    motiveFitConfirmed = !lockCam;
    refreshCalibrationUiState();
}
